import { useEffect, useMemo, useState } from 'react'
import { Header } from './components/Header'
import { ExerciseSidebar } from './components/ExerciseSidebar'
import { SchemaExplorer } from './components/SchemaExplorer'
import { Workspace } from './components/Workspace'
import { InitScreen } from './components/InitScreen'
import { useDatabase } from './hooks/useDatabase'
import { useTheme } from './hooks/useTheme'
import { useProgressStore } from './features/progress/store'
import { ALL_EXERCISES, EXERCISE_BY_ID, getNextExercise, getPrevExercise } from './data/exercises'

function App() {
  const dbState = useDatabase()
  const [theme, toggleTheme] = useTheme()

  const hasHydrated = useProgressStore((s) => s.hasHydrated)
  const storedCurrentId = useProgressStore((s) => s.currentExerciseId)
  const setCurrentExercise = useProgressStore((s) => s.setCurrentExercise)
  const exercisesProgress = useProgressStore((s) => s.exercises)
  const resetAllProgress = useProgressStore((s) => s.resetAllProgress)

  const [leftOpen, setLeftOpen] = useState(false)
  const [rightOpen, setRightOpen] = useState(false)

  const currentExerciseId = storedCurrentId && EXERCISE_BY_ID[storedCurrentId] ? storedCurrentId : ALL_EXERCISES[0].id
  const exercise = EXERCISE_BY_ID[currentExerciseId]

  useEffect(() => {
    if (hasHydrated && !storedCurrentId) {
      setCurrentExercise(ALL_EXERCISES[0].id)
    }
  }, [hasHydrated, storedCurrentId, setCurrentExercise])

  const completedCount = useMemo(() => Object.values(exercisesProgress).filter((e) => e.status === 'completed').length, [exercisesProgress])

  function selectExercise(id: string) {
    setCurrentExercise(id)
    setLeftOpen(false)
  }

  const prev = getPrevExercise(exercise.id)
  const next = getNextExercise(exercise.id)

  function handleResetProgress() {
    if (window.confirm('Reset all progress? This clears completion status and attempt counts for every exercise. Query history is kept.')) {
      resetAllProgress()
    }
  }

  if (dbState.status === 'error') {
    return (
      <div className="flex h-dvh w-full flex-col items-center justify-center gap-3 bg-canvas px-6 text-center text-text-primary">
        <h1 className="text-lg font-semibold text-danger">Database failed to start</h1>
        <p className="max-w-md text-sm text-text-secondary">{dbState.message}</p>
        <button onClick={() => window.location.reload()} className="mt-2 rounded-md bg-accent px-4 py-2 text-sm font-medium text-canvas">
          Reload
        </button>
      </div>
    )
  }

  if (dbState.status === 'initializing' || !hasHydrated) {
    return <InitScreen progress={dbState.status === 'initializing' ? dbState.progress : { phase: 'ready', completed: 1, total: 1, message: 'Loading progress...' }} />
  }

  return (
    <div className="flex h-dvh w-full flex-col overflow-hidden bg-canvas text-text-primary">
      <Header
        theme={theme}
        onToggleTheme={toggleTheme}
        onToggleLeftPanel={() => setLeftOpen((v) => !v)}
        onToggleRightPanel={() => setRightOpen((v) => !v)}
        onResetProgress={handleResetProgress}
        completedCount={completedCount}
        totalCount={ALL_EXERCISES.length}
      />

      <div className="relative flex min-h-0 flex-1 overflow-hidden">
        <aside
          className={`absolute inset-y-0 left-0 z-20 w-72 border-r border-border-subtle bg-canvas shadow-xl transition-transform lg:static lg:z-auto lg:w-64 lg:translate-x-0 lg:shadow-none ${
            leftOpen ? 'translate-x-0' : '-translate-x-full'
          }`}
        >
          <ExerciseSidebar currentExerciseId={exercise.id} onSelect={selectExercise} />
        </aside>
        {leftOpen && <div className="fixed inset-0 z-10 bg-black/40 lg:hidden" onClick={() => setLeftOpen(false)} />}

        <Workspace
          key={exercise.id}
          exercise={exercise}
          theme={theme}
          onPrev={prev ? () => selectExercise(prev.id) : undefined}
          onNext={next ? () => selectExercise(next.id) : undefined}
          hasPrev={!!prev}
          hasNext={!!next}
        />

        <aside
          className={`absolute inset-y-0 right-0 z-20 w-80 border-l border-border-subtle bg-canvas shadow-xl transition-transform xl:static xl:z-auto xl:w-80 xl:translate-x-0 xl:shadow-none ${
            rightOpen ? 'translate-x-0' : 'translate-x-full'
          }`}
        >
          <SchemaExplorer />
        </aside>
        {rightOpen && <div className="fixed inset-0 z-10 bg-black/40 xl:hidden" onClick={() => setRightOpen(false)} />}
      </div>
    </div>
  )
}

export default App

import { Component, type ErrorInfo, type ReactNode } from 'react'

interface Props {
  children: ReactNode
}

interface State {
  error: Error | null
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null }

  static getDerivedStateFromError(error: Error): State {
    return { error }
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error('ErrorBoundary caught:', error, info.componentStack)
  }

  render() {
    if (this.state.error) {
      return (
        <div className="flex h-dvh w-full flex-col items-center justify-center gap-3 bg-canvas px-6 text-center text-text-primary">
          <h1 className="text-lg font-semibold text-danger">Something went wrong</h1>
          <pre className="max-w-2xl overflow-auto whitespace-pre-wrap text-left text-xs text-text-secondary">
            {this.state.error.message}
            {'\n\n'}
            {this.state.error.stack}
          </pre>
          <button onClick={() => window.location.reload()} className="mt-2 rounded-md bg-accent px-4 py-2 text-sm font-medium text-canvas">
            Reload
          </button>
        </div>
      )
    }
    return this.props.children
  }
}

import { ChevronLeft, ChevronRight, Lightbulb, Sparkles } from 'lucide-react'
import { useState } from 'react'
import type { Exercise } from '../types'

interface ExercisePanelProps {
  exercise: Exercise
  isCompleted: boolean
  onPrev?: () => void
  onNext?: () => void
  hasPrev: boolean
  hasNext: boolean
}

export function ExercisePanel({ exercise, isCompleted, onPrev, onNext, hasPrev, hasNext }: ExercisePanelProps) {
  const [revealedHints, setRevealedHints] = useState(0)
  const [showSolution, setShowSolution] = useState(false)

  return (
    <div className="flex h-full flex-col overflow-y-auto px-5 py-4">
      <div className="mb-1 flex items-center justify-between">
        <div className="flex items-center gap-2 text-[11px] font-medium uppercase tracking-wide text-text-muted">
          <span>Level {exercise.level}</span>
          <span>·</span>
          <span>Difficulty {exercise.difficultyScore}/10</span>
          {isCompleted && <span className="rounded-full bg-success/15 px-2 py-0.5 text-success">Completed</span>}
        </div>
        <div className="flex items-center gap-1">
          <button
            onClick={onPrev}
            disabled={!hasPrev}
            className="rounded p-1 text-text-muted hover:bg-surface-hover hover:text-text-primary disabled:pointer-events-none disabled:opacity-30"
            title="Previous exercise"
          >
            <ChevronLeft className="h-4 w-4" />
          </button>
          <button
            onClick={onNext}
            disabled={!hasNext}
            className="rounded p-1 text-text-muted hover:bg-surface-hover hover:text-text-primary disabled:pointer-events-none disabled:opacity-30"
            title="Next exercise"
          >
            <ChevronRight className="h-4 w-4" />
          </button>
        </div>
      </div>

      <h2 className="text-lg font-semibold text-text-primary">{exercise.title}</h2>

      <p className="mt-2 whitespace-pre-line text-sm leading-relaxed text-text-secondary">{exercise.description}</p>

      {exercise.requirements && exercise.requirements.length > 0 && (
        <div className="mt-3">
          <div className="text-[11px] font-semibold uppercase tracking-wide text-text-muted">Requirements</div>
          <ul className="mt-1.5 space-y-1">
            {exercise.requirements.map((r, i) => (
              <li key={i} className="flex gap-1.5 text-xs text-text-secondary">
                <span className="text-accent">•</span>
                <span>{r}</span>
              </li>
            ))}
          </ul>
        </div>
      )}

      <div className="mt-3 flex flex-wrap gap-1.5">
        {exercise.conceptTags.map((tag) => (
          <span key={tag} className="rounded-full border border-border-subtle bg-surface-raised px-2 py-0.5 text-[10px] text-text-secondary">
            {tag}
          </span>
        ))}
      </div>

      <div className="mt-3 text-[11px] text-text-muted">
        Tables: <span className="font-mono">{exercise.tablesInvolved.join(', ')}</span>
      </div>

      {exercise.hints.length > 0 && (
        <div className="mt-5 border-t border-border-subtle pt-4">
          <div className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-text-muted">
            <Lightbulb className="h-3.5 w-3.5" />
            Hints
          </div>
          <div className="mt-2 space-y-2">
            {exercise.hints.slice(0, revealedHints).map((hint) => (
              <div key={hint.order} className="rounded-lg border border-border-subtle bg-surface-raised px-3 py-2 text-xs text-text-secondary">
                {hint.text}
              </div>
            ))}
          </div>
          {revealedHints < exercise.hints.length && (
            <button
              onClick={() => setRevealedHints((n) => n + 1)}
              className="mt-2 rounded-md border border-border-subtle px-2.5 py-1 text-[11px] text-text-secondary hover:border-accent hover:text-accent"
            >
              Reveal hint {revealedHints + 1} of {exercise.hints.length}
            </button>
          )}
        </div>
      )}

      {isCompleted && (
        <div className="mt-5 border-t border-border-subtle pt-4">
          {!showSolution ? (
            <button
              onClick={() => setShowSolution(true)}
              className="flex items-center gap-1.5 rounded-md border border-border-subtle px-2.5 py-1.5 text-[11px] text-text-secondary hover:border-accent hover:text-accent"
            >
              <Sparkles className="h-3.5 w-3.5" />
              Show official solution
            </button>
          ) : (
            <div>
              <div className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-text-muted">
                <Sparkles className="h-3.5 w-3.5" />
                Official solution
              </div>
              <pre className="mt-2 overflow-x-auto rounded-lg border border-border-subtle bg-surface-raised p-3 font-mono text-[11px] text-text-primary">
                {exercise.solution.sql}
              </pre>
              <p className="mt-2 text-xs leading-relaxed text-text-secondary">{exercise.solution.explanation}</p>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

import { CheckCircle2, ChevronDown, Circle, PlayCircle } from 'lucide-react'
import { useState } from 'react'
import { LEVELS } from '../data/levels'
import { EXERCISES_BY_LEVEL } from '../data/exercises'
import { useProgressStore } from '../features/progress/store'

interface ExerciseSidebarProps {
  currentExerciseId: string
  onSelect: (id: string) => void
}

export function ExerciseSidebar({ currentExerciseId, onSelect }: ExerciseSidebarProps) {
  const exercises = useProgressStore((s) => s.exercises)
  const activeLevelFromCurrent = Object.values(EXERCISES_BY_LEVEL)
    .flat()
    .find((e) => e.id === currentExerciseId)?.level
  const [openLevel, setOpenLevel] = useState<number>(activeLevelFromCurrent ?? 1)

  return (
    <nav className="flex h-full flex-col overflow-y-auto bg-surface">
      {LEVELS.map((level) => {
        const levelExercises = EXERCISES_BY_LEVEL[level.id] ?? []
        const completedCount = levelExercises.filter((e) => exercises[e.id]?.status === 'completed').length
        const isOpen = openLevel === level.id

        return (
          <div key={level.id} className="border-b border-border-subtle">
            <button
              onClick={() => setOpenLevel(isOpen ? -1 : level.id)}
              className="flex w-full items-center gap-2 px-3 py-2.5 text-left hover:bg-surface-hover"
            >
              <ChevronDown className={`h-3.5 w-3.5 shrink-0 text-text-muted transition-transform ${isOpen ? '' : '-rotate-90'}`} />
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="text-xs font-semibold text-text-primary">
                    L{level.id} · {level.title}
                  </span>
                </div>
                <div className="mt-0.5 text-[10px] text-text-muted">{level.subtitle}</div>
              </div>
              <span className="shrink-0 rounded-full bg-surface-raised px-1.5 py-0.5 text-[10px] tabular-nums text-text-secondary">
                {completedCount}/{levelExercises.length}
              </span>
            </button>

            {isOpen && (
              <ul className="pb-1">
                {levelExercises.map((ex) => {
                  const progress = exercises[ex.id]
                  const isActive = ex.id === currentExerciseId
                  return (
                    <li key={ex.id}>
                      <button
                        onClick={() => onSelect(ex.id)}
                        className={`flex w-full items-center gap-2 px-3 py-1.5 pl-8 text-left text-xs transition-colors ${
                          isActive ? 'bg-accent/10 text-accent' : 'text-text-secondary hover:bg-surface-hover hover:text-text-primary'
                        }`}
                      >
                        <StatusIcon status={progress?.status ?? 'unattempted'} active={isActive} />
                        <span className="min-w-0 flex-1 truncate">{ex.title}</span>
                        <DifficultyDots score={ex.difficultyScore} />
                      </button>
                    </li>
                  )
                })}
              </ul>
            )}
          </div>
        )
      })}
    </nav>
  )
}

function StatusIcon({ status, active }: { status: 'unattempted' | 'attempted' | 'completed'; active: boolean }) {
  if (status === 'completed') return <CheckCircle2 className="h-3.5 w-3.5 shrink-0 text-success" />
  if (status === 'attempted') return <PlayCircle className={`h-3.5 w-3.5 shrink-0 ${active ? 'text-accent' : 'text-warning'}`} />
  return <Circle className={`h-3.5 w-3.5 shrink-0 ${active ? 'text-accent' : 'text-text-muted'}`} />
}

function DifficultyDots({ score }: { score: number }) {
  const filled = Math.max(1, Math.round(score / 2))
  return (
    <span className="flex shrink-0 items-center gap-0.5" title={`Difficulty ${score}/10`}>
      {Array.from({ length: 5 }, (_, i) => (
        <span key={i} className={`h-1 w-1 rounded-full ${i < filled ? 'bg-text-secondary' : 'bg-border'}`} />
      ))}
    </span>
  )
}

import { AlertTriangle, CheckCircle2, Clock, History, RotateCcw, Table2, Trash2, XCircle } from 'lucide-react'
import { useState } from 'react'
import { ResultsTable } from './ResultsTable'
import type { QueryExecution, QueryHistoryEntry, ValidationResult } from '../types'

interface ResultPanelProps {
  execution: QueryExecution
  validation: ValidationResult | null
  history: QueryHistoryEntry[]
  onRestoreHistory: (sql: string) => void
  onDeleteHistory: (id: string) => void
}

type Tab = 'results' | 'history'

export function ResultPanel({ execution, validation, history, onRestoreHistory, onDeleteHistory }: ResultPanelProps) {
  const [tab, setTab] = useState<Tab>('results')

  return (
    <div className="flex h-full flex-col overflow-hidden bg-surface">
      {validation && <ValidationBanner validation={validation} />}

      <div className="flex items-center gap-1 border-b border-border-subtle px-2 pt-1.5">
        <TabButton active={tab === 'results'} onClick={() => setTab('results')} icon={<Table2 className="h-3.5 w-3.5" />} label="Results" />
        <TabButton active={tab === 'history'} onClick={() => setTab('history')} icon={<History className="h-3.5 w-3.5" />} label={`History (${history.length})`} />
        <div className="ml-auto pr-2 text-[11px] text-text-muted">
          {execution.status === 'success' && (
            <span className="flex items-center gap-1">
              <Clock className="h-3 w-3" /> {execution.result.durationMs.toFixed(0)}ms · {execution.result.rowCount.toLocaleString()} rows
            </span>
          )}
        </div>
      </div>

      <div className="min-h-0 flex-1 overflow-hidden">
        {tab === 'results' && <ResultsTab execution={execution} />}
        {tab === 'history' && <HistoryTab history={history} onRestore={onRestoreHistory} onDelete={onDeleteHistory} />}
      </div>
    </div>
  )
}

function TabButton({ active, onClick, icon, label }: { active: boolean; onClick: () => void; icon: React.ReactNode; label: string }) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 rounded-t-md px-3 py-1.5 text-xs font-medium transition-colors ${
        active ? 'bg-surface-raised text-text-primary' : 'text-text-secondary hover:text-text-primary'
      }`}
    >
      {icon}
      {label}
    </button>
  )
}

function ValidationBanner({ validation }: { validation: ValidationResult }) {
  const ok = validation.status === 'ok'
  return (
    <div className={`flex items-start gap-2 border-b px-4 py-3 ${ok ? 'border-success/30 bg-success/10' : 'border-danger/30 bg-danger/10'}`}>
      {ok ? <CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-success" /> : <XCircle className="mt-0.5 h-4 w-4 shrink-0 text-danger" />}
      <div className="min-w-0">
        <div className={`text-sm font-semibold ${ok ? 'text-success' : 'text-danger'}`}>{ok ? 'OK — Correct!' : 'KO — Not quite'}</div>
        <div className="mt-0.5 text-xs text-text-secondary">{validation.message}</div>
        {validation.detail && <div className="mt-1 font-mono text-[11px] text-text-muted">{validation.detail}</div>}
      </div>
    </div>
  )
}

function ResultsTab({ execution }: { execution: QueryExecution }) {
  if (execution.status === 'idle') {
    return <div className="p-4 text-sm text-text-secondary">Run a query to see results here. (Ctrl/Cmd + Enter)</div>
  }
  if (execution.status === 'running') {
    return <div className="p-4 text-sm text-text-secondary">Running query...</div>
  }
  if (execution.status === 'timeout') {
    return (
      <div className="flex items-start gap-2 p-4 text-sm text-warning">
        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
        <span>Query timed out. Try adding filters or a LIMIT clause.</span>
      </div>
    )
  }
  if (execution.status === 'error') {
    return (
      <div className="flex items-start gap-2 p-4 text-sm text-danger">
        <XCircle className="mt-0.5 h-4 w-4 shrink-0" />
        <div>
          <div className="font-mono text-xs">{execution.error.message}</div>
          {execution.error.hint && <div className="mt-1 text-xs text-text-muted">Hint: {execution.error.hint}</div>}
          {execution.error.position && <div className="mt-1 text-xs text-text-muted">Position: {execution.error.position}</div>}
        </div>
      </div>
    )
  }
  return <ResultsTable result={execution.result} />
}

function HistoryTab({ history, onRestore, onDelete }: { history: QueryHistoryEntry[]; onRestore: (sql: string) => void; onDelete: (id: string) => void }) {
  if (history.length === 0) {
    return <div className="p-4 text-sm text-text-secondary">No queries run yet for this exercise.</div>
  }
  return (
    <div className="h-full overflow-y-auto">
      {history.map((entry) => (
        <div key={entry.id} className="group flex items-start gap-2 border-b border-border-subtle px-3 py-2 hover:bg-surface-hover">
          <OutcomeDot outcome={entry.outcome} />
          <button onClick={() => onRestore(entry.sql)} className="min-w-0 flex-1 text-left">
            <pre className="whitespace-pre-wrap break-all font-mono text-[11px] text-text-secondary group-hover:text-text-primary">{entry.sql}</pre>
            <div className="mt-0.5 text-[10px] text-text-muted">{new Date(entry.ranAt).toLocaleTimeString()}</div>
          </button>
          <div className="flex shrink-0 items-center gap-1 opacity-0 group-hover:opacity-100">
            <button onClick={() => onRestore(entry.sql)} title="Restore" className="rounded p-1 text-text-muted hover:bg-surface-hover hover:text-accent">
              <RotateCcw className="h-3.5 w-3.5" />
            </button>
            <button onClick={() => onDelete(entry.id)} title="Delete" className="rounded p-1 text-text-muted hover:bg-surface-hover hover:text-danger">
              <Trash2 className="h-3.5 w-3.5" />
            </button>
          </div>
        </div>
      ))}
    </div>
  )
}

function OutcomeDot({ outcome }: { outcome: QueryHistoryEntry['outcome'] }) {
  const color =
    outcome === 'submit-ok' ? 'bg-success' : outcome === 'submit-ko' ? 'bg-danger' : outcome === 'run-error' ? 'bg-warning' : 'bg-text-muted'
  return <div className={`mt-1.5 h-1.5 w-1.5 shrink-0 rounded-full ${color}`} title={outcome} />
}

import type { QueryResult } from '../types'

const MAX_RENDERED_ROWS = 300

function formatCell(value: unknown): string {
  if (value === null || value === undefined) return 'NULL'
  if (typeof value === 'boolean') return value ? 'true' : 'false'
  if (typeof value === 'object') return JSON.stringify(value)
  return String(value)
}

export function ResultsTable({ result }: { result: QueryResult }) {
  if (result.columns.length === 0) {
    return <div className="p-4 text-sm text-text-secondary">Query executed successfully — no columns returned.</div>
  }
  if (result.rows.length === 0) {
    return <div className="p-4 text-sm text-text-secondary">Query executed successfully — 0 rows returned.</div>
  }

  const rows = result.rows.slice(0, MAX_RENDERED_ROWS)
  const truncated = result.rows.length > MAX_RENDERED_ROWS

  return (
    <div className="flex h-full flex-col overflow-hidden">
      <div className="flex-1 overflow-auto">
        <table className="w-full border-collapse text-left text-xs">
          <thead className="sticky top-0 z-10 bg-surface-raised">
            <tr>
              {result.columns.map((col) => (
                <th key={col.name} className="whitespace-nowrap border-b border-border px-3 py-2 font-medium text-text-secondary">
                  {col.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row, i) => (
              <tr key={i} className="odd:bg-transparent even:bg-surface-hover/30 hover:bg-surface-hover">
                {result.columns.map((col) => {
                  const raw = row[col.name]
                  const isNull = raw === null || raw === undefined
                  return (
                    <td key={col.name} className={`whitespace-nowrap border-b border-border-subtle px-3 py-1.5 font-mono ${isNull ? 'italic text-text-muted' : 'text-text-primary'}`}>
                      {formatCell(raw)}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {truncated && (
        <div className="border-t border-border-subtle bg-surface px-3 py-1.5 text-[11px] text-text-muted">
          Showing first {MAX_RENDERED_ROWS.toLocaleString()} of {result.rowCount.toLocaleString()} rows.
        </div>
      )}
    </div>
  )
}

import { Eye, Key, Link2, Table } from 'lucide-react'
import { useState } from 'react'
import { DATABASE_TABLES } from '../data/schemaExplorer'
import { previewTable } from '../database/db'
import type { QueryResult } from '../types'
import { ResultsTable } from './ResultsTable'

const CATEGORY_LABELS: Record<string, string> = {
  people: 'People',
  catalog: 'Catalog',
  commerce: 'Commerce',
  engagement: 'Engagement',
  support: 'Support',
  reference: 'Reference',
}

export function SchemaExplorer() {
  const [selected, setSelected] = useState<string | null>(null)
  const [preview, setPreview] = useState<QueryResult | null>(null)
  const [loadingPreview, setLoadingPreview] = useState(false)

  const table = DATABASE_TABLES.find((t) => t.name === selected)

  const grouped = DATABASE_TABLES.reduce<Record<string, typeof DATABASE_TABLES>>((acc, t) => {
    ;(acc[t.category] ??= []).push(t)
    return acc
  }, {})

  async function handleSelect(name: string) {
    setSelected(name)
    setPreview(null)
  }

  async function handlePreview() {
    if (!table) return
    setLoadingPreview(true)
    try {
      const result = await previewTable(table.name, 15)
      setPreview(result)
    } catch {
      setPreview(null)
    } finally {
      setLoadingPreview(false)
    }
  }

  if (table) {
    return (
      <div className="flex h-full flex-col overflow-hidden bg-surface">
        <div className="flex items-center gap-2 border-b border-border-subtle px-3 py-2.5">
          <button onClick={() => setSelected(null)} className="text-xs text-text-secondary hover:text-accent">
            ← Tables
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-y-auto px-3 py-3">
          <div className="flex items-center gap-2">
            <Table className="h-4 w-4 text-accent" />
            <h3 className="font-mono text-sm font-semibold text-text-primary">{table.name}</h3>
          </div>
          <p className="mt-1.5 text-xs leading-relaxed text-text-secondary">{table.description}</p>
          <p className="mt-1 text-[10px] text-text-muted">~{table.rowCountApprox.toLocaleString()} rows</p>

          <button
            onClick={handlePreview}
            disabled={loadingPreview}
            className="mt-3 flex items-center gap-1.5 rounded-md border border-border-subtle px-2.5 py-1.5 text-[11px] text-text-secondary hover:border-accent hover:text-accent disabled:opacity-50"
          >
            <Eye className="h-3.5 w-3.5" />
            {loadingPreview ? 'Loading...' : 'Preview 15 rows'}
          </button>

          <div className="mt-4 space-y-1">
            {table.columns.map((col) => (
              <div key={col.name} className="rounded-md border border-border-subtle bg-surface-raised px-2.5 py-1.5">
                <div className="flex items-center gap-1.5">
                  {col.isPrimaryKey && <Key className="h-3 w-3 shrink-0 text-warning" />}
                  {col.isForeignKey && !col.isPrimaryKey && <Link2 className="h-3 w-3 shrink-0 text-accent" />}
                  <span className="font-mono text-xs text-text-primary">{col.name}</span>
                  <span className="ml-auto font-mono text-[10px] text-text-muted">{col.type}</span>
                </div>
                {(col.references || col.description) && (
                  <div className="mt-0.5 pl-[1.125rem] text-[10px] text-text-muted">
                    {col.references && (
                      <span>
                        → {col.references.table}.{col.references.column}
                      </span>
                    )}
                    {col.description && <span>{col.references ? ' · ' : ''}{col.description}</span>}
                  </div>
                )}
                {!col.nullable && <span className="ml-[1.125rem] text-[9px] uppercase text-text-muted">not null</span>}
              </div>
            ))}
          </div>
        </div>
        {preview && (
          <div className="h-56 shrink-0 border-t border-border-subtle">
            <ResultsTable result={preview} />
          </div>
        )}
      </div>
    )
  }

  return (
    <div className="flex h-full flex-col overflow-y-auto bg-surface">
      {Object.entries(grouped).map(([category, tables]) => (
        <div key={category} className="border-b border-border-subtle">
          <div className="px-3 pt-2.5 text-[10px] font-semibold uppercase tracking-wide text-text-muted">{CATEGORY_LABELS[category] ?? category}</div>
          <ul className="pb-1.5">
            {tables.map((t) => (
              <li key={t.name}>
                <button
                  onClick={() => handleSelect(t.name)}
                  className="flex w-full items-center gap-2 px-3 py-1.5 text-left text-xs text-text-secondary hover:bg-surface-hover hover:text-text-primary"
                >
                  <Table className="h-3.5 w-3.5 shrink-0 text-text-muted" />
                  <span className="min-w-0 flex-1 truncate font-mono">{t.name}</span>
                  <span className="shrink-0 text-[10px] text-text-muted">{t.columns.length} cols</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </div>
  )
}

import { lazy, Suspense, useMemo, useState } from 'react'
import { ExercisePanel } from './ExercisePanel'
import { EditorToolbar } from './EditorToolbar'
import { ResultPanel } from './ResultPanel'
import { formatSql } from '../features/editor/formatSql'
import { runUserQuery, toQueryError } from '../database/db'
import { validateSubmission } from '../features/validation/validate'
import { useProgressStore } from '../features/progress/store'
import { useHistoryStore } from '../features/progress/historyStore'
import type { Exercise, QueryExecution, ValidationResult } from '../types'
import type { Theme } from '../hooks/useTheme'

const SqlEditor = lazy(() => import('../features/editor/SqlEditor').then((m) => ({ default: m.SqlEditor })))

const DEFAULT_STARTER = '-- Write your PostgreSQL query here\n\n'

interface WorkspaceProps {
  exercise: Exercise
  theme: Theme
  onPrev?: () => void
  onNext?: () => void
  hasPrev: boolean
  hasNext: boolean
}

export function Workspace({ exercise, theme, onPrev, onNext, hasPrev, hasNext }: WorkspaceProps) {
  const progress = useProgressStore((s) => s.exercises[exercise.id])
  const recordAttempt = useProgressStore((s) => s.recordAttempt)
  const recordSubmission = useProgressStore((s) => s.recordSubmission)
  const allHistoryEntries = useHistoryStore((s) => s.entries)
  const historyEntries = useMemo(
    () => allHistoryEntries.filter((e) => e.exerciseId === exercise.id).sort((a, b) => b.ranAt - a.ranAt),
    [allHistoryEntries, exercise.id],
  )
  const addHistoryEntry = useHistoryStore((s) => s.addEntry)
  const deleteHistoryEntry = useHistoryStore((s) => s.deleteEntry)

  const [sql, setSql] = useState(() => progress?.lastQuery ?? exercise.starterQuery ?? DEFAULT_STARTER)
  const [execution, setExecution] = useState<QueryExecution>({ status: 'idle' })
  const [validation, setValidation] = useState<ValidationResult | null>(null)

  const isCompleted = progress?.status === 'completed'

  async function handleRun() {
    if (execution.status === 'running') return
    setExecution({ status: 'running' })
    setValidation(null)
    try {
      const result = await runUserQuery(sql)
      setExecution({ status: 'success', result })
      recordAttempt(exercise.id, sql)
      addHistoryEntry(exercise.id, sql, 'run-success')
    } catch (err) {
      const error = toQueryError(err)
      setExecution({ status: 'error', error })
      recordAttempt(exercise.id, sql)
      addHistoryEntry(exercise.id, sql, 'run-error')
    }
  }

  async function handleSubmit() {
    if (execution.status === 'running') return
    setExecution({ status: 'running' })
    setValidation(null)
    const { validation: result, userResult } = await validateSubmission(exercise, sql)
    setValidation(result)
    if (userResult) {
      setExecution({ status: 'success', result: userResult })
    } else {
      setExecution({ status: 'error', error: { message: result.message, detail: result.detail } })
    }
    const ok = result.status === 'ok'
    recordSubmission(exercise.id, ok, sql)
    addHistoryEntry(exercise.id, sql, ok ? 'submit-ok' : 'submit-ko')
  }

  function handleFormat() {
    setSql((prev) => formatSql(prev))
  }

  function handleReset() {
    setSql(exercise.starterQuery ?? DEFAULT_STARTER)
    setExecution({ status: 'idle' })
    setValidation(null)
  }

  function handleRestoreHistory(restoredSql: string) {
    setSql(restoredSql)
  }

  return (
    <div className="flex min-h-0 flex-1 flex-col lg:flex-row">
      <div className="h-64 shrink-0 overflow-hidden border-b border-border-subtle lg:h-auto lg:w-[380px] lg:border-b-0 lg:border-r">
        <ExercisePanel exercise={exercise} isCompleted={isCompleted} onPrev={onPrev} onNext={onNext} hasPrev={hasPrev} hasNext={hasNext} />
      </div>

      <div className="flex min-h-0 flex-1 flex-col">
        <EditorToolbar
          onRun={handleRun}
          onSubmit={handleSubmit}
          onFormat={handleFormat}
          onReset={handleReset}
          isRunning={execution.status === 'running' && !validation}
          isSubmitting={execution.status === 'running'}
        />
        <div className="h-64 min-h-[160px] shrink-0 border-b border-border-subtle lg:h-2/5">
          <Suspense fallback={<div className="flex h-full items-center justify-center text-xs text-text-muted">Loading editor...</div>}>
            <SqlEditor value={sql} onChange={setSql} onRun={handleRun} theme={theme} />
          </Suspense>
        </div>
        <div className="min-h-0 flex-1">
          <ResultPanel execution={execution} validation={validation} history={historyEntries} onRestoreHistory={handleRestoreHistory} onDeleteHistory={deleteHistoryEntry} />
        </div>
      </div>
    </div>
  )
}

