import { describe, expect, it } from 'vitest'
import { ALL_EXERCISES, EXERCISES_BY_LEVEL, getNextExercise, getPrevExercise } from './index'
import { LEVELS } from '../levels'

describe('exercise dataset integrity', () => {
  it('has a substantial curriculum', () => {
    expect(ALL_EXERCISES.length).toBeGreaterThanOrEqual(120)
  })

  it('has every exercise id unique', () => {
    const ids = ALL_EXERCISES.map((e) => e.id)
    expect(new Set(ids).size).toBe(ids.length)
  })

  it('assigns every exercise to one of the 10 defined levels', () => {
    const levelIds = new Set(LEVELS.map((l) => l.id))
    for (const ex of ALL_EXERCISES) {
      expect(levelIds.has(ex.level)).toBe(true)
    }
  })

  it('gives every level at least 10 exercises', () => {
    for (const level of LEVELS) {
      expect(EXERCISES_BY_LEVEL[level.id]?.length ?? 0).toBeGreaterThanOrEqual(10)
    }
  })

  it('orders exercises within a level starting at 1 with no gaps or duplicates', () => {
    for (const level of LEVELS) {
      const orders = (EXERCISES_BY_LEVEL[level.id] ?? []).map((e) => e.order).sort((a, b) => a - b)
      expect(orders).toEqual(Array.from({ length: orders.length }, (_, i) => i + 1))
    }
  })

  it('gives every exercise a non-empty solution query and explanation', () => {
    for (const ex of ALL_EXERCISES) {
      expect(ex.solution.sql.trim().length, `${ex.id} solution.sql`).toBeGreaterThan(0)
      expect(ex.solution.explanation.trim().length, `${ex.id} solution.explanation`).toBeGreaterThan(0)
    }
  })

  it('gives every exercise at least one hint', () => {
    for (const ex of ALL_EXERCISES) {
      expect(ex.hints.length, `${ex.id} hints`).toBeGreaterThan(0)
    }
  })

  it('gives every exercise at least one concept tag and one involved table', () => {
    for (const ex of ALL_EXERCISES) {
      expect(ex.conceptTags.length, `${ex.id} conceptTags`).toBeGreaterThan(0)
      expect(ex.tablesInvolved.length, `${ex.id} tablesInvolved`).toBeGreaterThan(0)
    }
  })

  it('keeps difficultyScore within 1-10', () => {
    for (const ex of ALL_EXERCISES) {
      expect(ex.difficultyScore).toBeGreaterThanOrEqual(1)
      expect(ex.difficultyScore).toBeLessThanOrEqual(10)
    }
  })

  it('numbers hints sequentially starting at 1', () => {
    for (const ex of ALL_EXERCISES) {
      const orders = ex.hints.map((h) => h.order)
      expect(orders, ex.id).toEqual(Array.from({ length: orders.length }, (_, i) => i + 1))
    }
  })
})

describe('exercise navigation', () => {
  it('walks forward from the first to the second exercise', () => {
    const next = getNextExercise(ALL_EXERCISES[0].id)
    expect(next?.id).toBe(ALL_EXERCISES[1].id)
  })

  it('returns undefined past the last exercise', () => {
    const last = ALL_EXERCISES[ALL_EXERCISES.length - 1]
    expect(getNextExercise(last.id)).toBeUndefined()
  })

  it('returns undefined before the first exercise', () => {
    expect(getPrevExercise(ALL_EXERCISES[0].id)).toBeUndefined()
  })

  it('walks backward correctly', () => {
    const prev = getPrevExercise(ALL_EXERCISES[2].id)
    expect(prev?.id).toBe(ALL_EXERCISES[1].id)
  })
})

import type { Exercise } from '../../types'
import { level1Exercises } from './level1'
import { level2Exercises } from './level2'
import { level3Exercises } from './level3'
import { level4Exercises } from './level4'
import { level5Exercises } from './level5'
import { level6Exercises } from './level6'
import { level7Exercises } from './level7'
import { level8Exercises } from './level8'
import { level9Exercises } from './level9'
import { level10Exercises } from './level10'

export const ALL_EXERCISES: Exercise[] = [
  ...level1Exercises,
  ...level2Exercises,
  ...level3Exercises,
  ...level4Exercises,
  ...level5Exercises,
  ...level6Exercises,
  ...level7Exercises,
  ...level8Exercises,
  ...level9Exercises,
  ...level10Exercises,
]

export const EXERCISES_BY_LEVEL: Record<number, Exercise[]> = ALL_EXERCISES.reduce(
  (acc, ex) => {
    ;(acc[ex.level] ??= []).push(ex)
    return acc
  },
  {} as Record<number, Exercise[]>,
)

for (const level of Object.keys(EXERCISES_BY_LEVEL)) {
  EXERCISES_BY_LEVEL[Number(level)].sort((a, b) => a.order - b.order)
}

export const EXERCISE_BY_ID: Record<string, Exercise> = Object.fromEntries(ALL_EXERCISES.map((ex) => [ex.id, ex]))

export function getExercise(id: string): Exercise | undefined {
  return EXERCISE_BY_ID[id]
}

export function getNextExercise(id: string): Exercise | undefined {
  const idx = ALL_EXERCISES.findIndex((e) => e.id === id)
  if (idx === -1 || idx === ALL_EXERCISES.length - 1) return undefined
  return ALL_EXERCISES[idx + 1]
}

export function getPrevExercise(id: string): Exercise | undefined {
  const idx = ALL_EXERCISES.findIndex((e) => e.id === id)
  if (idx <= 0) return undefined
  return ALL_EXERCISES[idx - 1]
}

import { PGliteWorker } from '@electric-sql/pglite/worker'
import type { QueryError, QueryResult } from '../types'
import { generateSeedStatements } from './seed'
import { GuardError, guardReadOnly } from './guard'
import schemaSql from './schema.sql?raw'

export type InitPhase = 'starting' | 'connecting' | 'checking' | 'schema' | 'seeding' | 'ready'

export interface InitProgress {
  phase: InitPhase
  completed: number
  total: number
  message: string
}

const STATEMENT_TIMEOUT_MS = 8000

let workerInstance: PGliteWorker | null = null
let readyPromise: Promise<void> | null = null

function getWorker(): PGliteWorker {
  if (!workerInstance) throw new Error('Database not initialized yet')
  return workerInstance
}

export async function initDatabase(onProgress?: (p: InitProgress) => void): Promise<void> {
  if (readyPromise) return readyPromise
  readyPromise = (async () => {
    const report = (p: InitProgress) => onProgress?.(p)
    report({ phase: 'starting', completed: 0, total: 1, message: 'Booting PGlite (WebAssembly Postgres)...' })

    const worker = new Worker(new URL('./pgWorker.ts', import.meta.url), { type: 'module' })
    const pg = await PGliteWorker.create(worker, { id: 'postgres-arena' })
    workerInstance = pg
    report({ phase: 'connecting', completed: 0, total: 1, message: 'Connecting to database engine...' })

    const existing = await pg.query<{ exists: boolean }>(
      `select exists (select 1 from information_schema.tables where table_schema = 'public' and table_name = 'orders') as exists`,
    )
    const alreadyInitialized = existing.rows[0]?.exists === true

    if (alreadyInitialized) {
      const countRes = await pg.query<{ count: string }>(`select count(*)::text as count from orders`)
      const rowCount = Number(countRes.rows[0]?.count ?? '0')
      if (rowCount > 0) {
        report({ phase: 'ready', completed: 1, total: 1, message: 'Database ready.' })
        return
      }
    }

    report({ phase: 'schema', completed: 0, total: 1, message: 'Creating schema (20 tables, enums, indexes)...' })
    await pg.exec(schemaSql)

    report({ phase: 'seeding', completed: 0, total: 1, message: 'Generating realistic seed dataset...' })
    const statements = generateSeedStatements()
    const total = statements.length
    let completed = 0
    const CHUNK = 6
    for (let i = 0; i < statements.length; i += CHUNK) {
      const chunk = statements.slice(i, i + CHUNK).join('\n')
      await pg.exec(chunk)
      completed = Math.min(i + CHUNK, total)
      report({ phase: 'seeding', completed, total, message: `Seeding data (${completed}/${total} batches)...` })
    }

    await pg.exec('analyze;')
    report({ phase: 'ready', completed: 1, total: 1, message: 'Database ready.' })
  })()
  return readyPromise
}

export function isReady(): boolean {
  return workerInstance !== null
}

/**
 * Executes a user-supplied read-only query inside a transaction that is
 * always rolled back, so the shared practice dataset can never be mutated.
 */
export async function runUserQuery(sql: string): Promise<QueryResult> {
  guardReadOnly(sql)
  const pg = getWorker()
  const start = performance.now()

  const outcome = await pg.transaction(async (tx) => {
    await tx.query(`set local statement_timeout = ${STATEMENT_TIMEOUT_MS}`)
    try {
      const res = await tx.query(sql)
      return { ok: true as const, res }
    } catch (err) {
      return { ok: false as const, err }
    } finally {
      await tx.rollback()
    }
  })

  const durationMs = performance.now() - start

  if (!outcome.ok) {
    throw toQueryError(outcome.err)
  }

  return {
    columns: outcome.res.fields.map((f) => ({ name: f.name, dataTypeId: f.dataTypeID })),
    rows: outcome.res.rows as Record<string, unknown>[],
    rowCount: outcome.res.rows.length,
    durationMs,
  }
}

export function toQueryError(err: unknown): QueryError {
  if (err instanceof GuardError) {
    return { message: err.message }
  }
  const e = err as { message?: string; detail?: string; hint?: string; position?: string; code?: string }
  return {
    message: e?.message ?? 'An unknown error occurred while running the query.',
    detail: e?.detail,
    hint: e?.hint,
    position: e?.position,
    code: e?.code,
  }
}

export async function previewTable(tableName: string, limit = 25): Promise<QueryResult> {
  if (!/^[a-z_][a-z0-9_]*$/.test(tableName)) throw new Error('Invalid table name')
  return runUserQuery(`select * from ${tableName} limit ${limit}`)
}

import { describe, expect, it } from 'vitest'
import { GuardError, guardReadOnly } from './guard'

describe('guardReadOnly', () => {
  it('allows a plain SELECT', () => {
    expect(() => guardReadOnly('SELECT * FROM products')).not.toThrow()
  })

  it('allows a WITH (CTE) query', () => {
    expect(() => guardReadOnly('WITH x AS (SELECT 1) SELECT * FROM x')).not.toThrow()
  })

  it('allows a trailing semicolon', () => {
    expect(() => guardReadOnly('SELECT 1;')).not.toThrow()
  })

  it('allows lowercase and mixed case', () => {
    expect(() => guardReadOnly('select * from products')).not.toThrow()
  })

  it('rejects an empty query', () => {
    expect(() => guardReadOnly('   ')).toThrow(GuardError)
  })

  it('rejects INSERT', () => {
    expect(() => guardReadOnly('INSERT INTO products (name) VALUES (1)')).toThrow(GuardError)
  })

  it('rejects UPDATE', () => {
    expect(() => guardReadOnly('UPDATE products SET price = 1')).toThrow(GuardError)
  })

  it('rejects DELETE', () => {
    expect(() => guardReadOnly('DELETE FROM products')).toThrow(GuardError)
  })

  it('rejects DROP TABLE', () => {
    expect(() => guardReadOnly('DROP TABLE products')).toThrow(GuardError)
  })

  it('rejects a second statement stacked after a semicolon', () => {
    expect(() => guardReadOnly('SELECT 1; DROP TABLE products;')).toThrow(GuardError)
  })

  it('rejects a query that does not start with a read-only keyword', () => {
    expect(() => guardReadOnly('EXEC something')).toThrow(GuardError)
  })

  it('rejects transaction control statements', () => {
    expect(() => guardReadOnly('BEGIN')).toThrow(GuardError)
    expect(() => guardReadOnly('COMMIT')).toThrow(GuardError)
  })

  it('allows a mutation keyword when it only appears inside a string literal-like context is still rejected (defense in depth)', () => {
    // The guard is intentionally strict/keyword-based rather than a full SQL
    // parser, so a SELECT that merely mentions a forbidden word is also blocked.
    expect(() => guardReadOnly("SELECT 'insert' AS word")).toThrow(GuardError)
  })
})

const ONLY_READ_PATTERN = /^\s*(select|with|table|values|explain)\b/i
const FORBIDDEN_PATTERN =
  /\b(insert|update|delete|drop|alter|truncate|grant|revoke|create|vacuum|reindex|cluster|copy|merge|call|do|listen|notify|begin|commit|rollback|savepoint|set\s+session|set\s+role)\b/i

export class GuardError extends Error {}

/** Rejects anything that isn't a single read-only statement, as a defense-in-depth
 * layer alongside the always-rolled-back transaction wrapper in db.ts. */
export function guardReadOnly(sql: string): void {
  const trimmed = sql.trim().replace(/;+\s*$/g, '')
  if (trimmed.length === 0) throw new GuardError('Query is empty.')

  const parts = trimmed.split(';')
  for (let i = 1; i < parts.length; i++) {
    if (parts[i].trim().length > 0) {
      throw new GuardError('Only a single SELECT statement is allowed. Remove any statements after the first semicolon.')
    }
  }

  if (!ONLY_READ_PATTERN.test(parts[0])) {
    throw new GuardError('Only read-only queries (SELECT / WITH / VALUES) are supported in Postgres Arena.')
  }
  if (FORBIDDEN_PATTERN.test(trimmed)) {
    throw new GuardError('This keyword is not allowed. Postgres Arena only runs read-only SELECT queries.')
  }
}

