/** Deterministic PRNG (mulberry32) so the seed dataset is 100% reproducible. */
export function mulberry32(seed: number) {
  let a = seed
  return function rand() {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export class Rng {
  private next: () => number

  constructor(seed: number) {
    this.next = mulberry32(seed)
  }

  float(): number {
    return this.next()
  }

  int(min: number, max: number): number {
    return Math.floor(this.next() * (max - min + 1)) + min
  }

  numeric(min: number, max: number, decimals = 2): number {
    const v = this.next() * (max - min) + min
    const f = Math.pow(10, decimals)
    return Math.round(v * f) / f
  }

  bool(trueProbability = 0.5): boolean {
    return this.next() < trueProbability
  }

  pick<T>(arr: readonly T[]): T {
    return arr[Math.floor(this.next() * arr.length)]
  }

  pickN<T>(arr: readonly T[], n: number): T[] {
    const pool = [...arr]
    const out: T[] = []
    for (let i = 0; i < n && pool.length > 0; i++) {
      const idx = Math.floor(this.next() * pool.length)
      out.push(pool.splice(idx, 1)[0])
    }
    return out
  }

  weighted<T>(items: readonly (readonly [T, number])[]): T {
    const total = items.reduce((sum, [, w]) => sum + w, 0)
    let r = this.next() * total
    for (const [item, w] of items) {
      r -= w
      if (r <= 0) return item
    }
    return items[items.length - 1][0]
  }

  dateBetween(start: Date, end: Date): Date {
    const t = start.getTime() + this.next() * (end.getTime() - start.getTime())
    return new Date(t)
  }

  uuid(): string {
    const hex = () => Math.floor(this.next() * 16).toString(16)
    const seg = (n: number) => Array.from({ length: n }, hex).join('')
    return `${seg(8)}-${seg(4)}-4${seg(3)}-${(8 + Math.floor(this.next() * 4)).toString(16)}${seg(3)}-${seg(12)}`
  }
}

-- ============================================================================
-- Postgres Arena practice database — "NorthStar Retail"
-- A mid-size e-commerce retailer: catalog, orders, payments, memberships,
-- support, HR org chart, and a behavioral event stream.
-- ============================================================================

-- ---------- Enum types --------------------------------------------------

create type product_status as enum ('active', 'discontinued', 'draft');
create type customer_tier as enum ('bronze', 'silver', 'gold', 'platinum');
create type order_status as enum ('pending', 'processing', 'shipped', 'delivered', 'cancelled', 'refunded');
create type payment_method as enum ('credit_card', 'paypal', 'bank_transfer', 'gift_card');
create type payment_status as enum ('pending', 'completed', 'failed', 'refunded');
create type membership_plan as enum ('basic', 'plus', 'premium', 'elite');
create type membership_status as enum ('active', 'trialing', 'cancelled', 'past_due');
create type ticket_status as enum ('open', 'pending', 'resolved', 'closed');
create type ticket_priority as enum ('low', 'medium', 'high', 'urgent');
create type message_sender as enum ('customer', 'agent');
create type address_kind as enum ('billing', 'shipping');

-- ---------- Reference / org tables --------------------------------------

create table departments (
  id serial primary key,
  name text not null,
  parent_department_id integer references departments(id),
  created_at timestamptz not null default now()
);

create table employees (
  id serial primary key,
  first_name text not null,
  last_name text not null,
  email text not null unique,
  department_id integer not null references departments(id),
  manager_id integer references employees(id),
  title text not null,
  salary numeric(10, 2) not null,
  hire_date date not null,
  termination_date date,
  is_active boolean not null default true,
  skills text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb
);

create table warehouses (
  id serial primary key,
  code text not null unique,
  name text not null,
  country text not null
);

-- ---------- Catalog -------------------------------------------------------

create table categories (
  id serial primary key,
  name text not null,
  slug text not null unique,
  parent_category_id integer references categories(id)
);

create table suppliers (
  id serial primary key,
  name text not null,
  country text not null,
  contact_email text not null,
  rating numeric(2, 1) not null check (rating between 0 and 5)
);

create table products (
  id uuid primary key,
  sku text not null unique,
  name text not null,
  category_id integer not null references categories(id),
  supplier_id integer not null references suppliers(id),
  price numeric(10, 2) not null,
  cost numeric(10, 2) not null,
  inventory_count integer not null default 0,
  status product_status not null default 'active',
  tags text[] not null default '{}',
  attributes jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  discontinued_at timestamptz
);

create table inventory (
  warehouse_id integer not null references warehouses(id),
  product_id uuid not null references products(id),
  quantity integer not null default 0,
  primary key (warehouse_id, product_id)
);

-- ---------- Customers ------------------------------------------------------

create table customers (
  id uuid primary key,
  email text not null unique,
  first_name text not null,
  last_name text not null,
  signup_date date not null,
  tier customer_tier not null default 'bronze',
  country text not null,
  birth_date date,
  marketing_opt_in boolean not null default true,
  referred_by uuid references customers(id),
  tags text[] not null default '{}',
  metadata jsonb not null default '{}'::jsonb
);

create table addresses (
  id serial primary key,
  customer_id uuid not null references customers(id),
  kind address_kind not null,
  line1 text not null,
  city text not null,
  country text not null,
  postal_code text not null,
  is_default boolean not null default false
);

create table memberships (
  id serial primary key,
  customer_id uuid not null references customers(id),
  plan membership_plan not null,
  status membership_status not null,
  monthly_fee numeric(6, 2) not null,
  started_at date not null,
  ended_at date
);

-- ---------- Commerce -------------------------------------------------------

create table coupons (
  id serial primary key,
  code text not null unique,
  discount_pct numeric(5, 2) not null,
  valid_from date not null,
  valid_to date not null,
  max_uses integer,
  applicable_category_ids integer[]
);

create table orders (
  id serial primary key,
  order_number text not null unique,
  customer_id uuid not null references customers(id),
  employee_id integer references employees(id),
  order_date timestamptz not null,
  status order_status not null default 'pending',
  shipping_address_id integer references addresses(id),
  notes text
);

create table order_items (
  id serial primary key,
  order_id integer not null references orders(id),
  product_id uuid not null references products(id),
  quantity integer not null check (quantity > 0),
  unit_price numeric(10, 2) not null,
  discount_pct numeric(4, 2) not null default 0
);

create table order_coupons (
  order_id integer not null references orders(id),
  coupon_id integer not null references coupons(id),
  primary key (order_id, coupon_id)
);

create table payments (
  id serial primary key,
  order_id integer not null references orders(id),
  amount numeric(10, 2) not null,
  paid_at timestamptz not null,
  method payment_method not null,
  status payment_status not null default 'completed'
);

create table reviews (
  id serial primary key,
  product_id uuid not null references products(id),
  customer_id uuid not null references customers(id),
  rating integer not null check (rating between 1 and 5),
  title text,
  body text,
  helpful_votes integer not null default 0,
  created_at timestamptz not null default now()
);

-- ---------- Support ---------------------------------------------------------

create table support_tickets (
  id serial primary key,
  customer_id uuid not null references customers(id),
  assigned_employee_id integer references employees(id),
  subject text not null,
  status ticket_status not null default 'open',
  priority ticket_priority not null default 'medium',
  created_at timestamptz not null,
  resolved_at timestamptz,
  satisfaction_score integer check (satisfaction_score between 1 and 5)
);

create table ticket_messages (
  id serial primary key,
  ticket_id integer not null references support_tickets(id),
  sender message_sender not null,
  body text not null,
  sent_at timestamptz not null
);

-- ---------- Behavioral events -------------------------------------------

create table events (
  id bigserial primary key,
  customer_id uuid references customers(id),
  session_id uuid not null,
  event_type text not null,
  occurred_at timestamptz not null,
  url text,
  properties jsonb not null default '{}'::jsonb
);

-- ---------- Indexes ----------------------------------------------------

create index idx_employees_department on employees(department_id);
create index idx_employees_manager on employees(manager_id);
create index idx_products_category on products(category_id);
create index idx_products_supplier on products(supplier_id);
create index idx_addresses_customer on addresses(customer_id);
create index idx_orders_customer on orders(customer_id);
create index idx_orders_employee on orders(employee_id);
create index idx_orders_date on orders(order_date);
create index idx_order_items_order on order_items(order_id);
create index idx_order_items_product on order_items(product_id);
create index idx_payments_order on payments(order_id);
create index idx_reviews_product on reviews(product_id);
create index idx_reviews_customer on reviews(customer_id);
create index idx_tickets_customer on support_tickets(customer_id);
create index idx_ticket_messages_ticket on ticket_messages(ticket_id);
create index idx_events_customer on events(customer_id);
create index idx_events_session on events(session_id);
create index idx_events_occurred on events(occurred_at);
create index idx_memberships_customer on memberships(customer_id);

import { Rng } from './rng'
import { batchedInserts, bool, dateOnly, insertStatement, intArray, json, num, str, textArray, ts } from './sqlLiterals'
import {
  BRANDS,
  CATEGORY_TREE,
  COUNTRIES,
  DEPARTMENTS,
  EVENT_TYPES,
  FIRST_NAMES,
  LAST_NAMES,
  PRODUCT_ADJECTIVES,
  PRODUCT_NOUNS,
  STREET_NAMES,
  TICKET_SUBJECTS,
} from './wordLists'

const SEED = 42
const DAY = 24 * 60 * 60 * 1000
const NOW = new Date('2026-08-15T00:00:00Z')

function fullName(rng: Rng) {
  return { first: rng.pick(FIRST_NAMES), last: rng.pick(LAST_NAMES) }
}

function slugify(s: string) {
  return s
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
}

/** Generates the entire seed dataset as an ordered list of executable SQL statements. */
export function generateSeedStatements(): string[] {
  const rng = new Rng(SEED)
  const statements: string[] = []

  // ---------------------------------------------------------------- departments
  const deptIdByName = new Map<string, number>()
  const deptRows: string[][] = []
  DEPARTMENTS.forEach((d, i) => {
    const id = i + 1
    deptIdByName.set(d.name, id)
    const parentId = d.parent ? deptIdByName.get(d.parent)! : null
    deptRows.push([num(id), str(d.name), num(parentId), ts(rng.dateBetween(new Date('2015-01-01'), new Date('2018-01-01')))])
  })
  statements.push(insertStatement('departments', ['id', 'name', 'parent_department_id', 'created_at'], deptRows))

  // ---------------------------------------------------------------- warehouses
  const warehouseDefs = [
    { code: 'WH-EAST', name: 'East Coast Fulfillment Center', country: 'United States' },
    { code: 'WH-WEST', name: 'West Coast Fulfillment Center', country: 'United States' },
    { code: 'WH-EU', name: 'European Distribution Hub', country: 'Germany' },
    { code: 'WH-UK', name: 'UK Distribution Center', country: 'United Kingdom' },
    { code: 'WH-APAC', name: 'APAC Fulfillment Center', country: 'Singapore' },
    { code: 'WH-LATAM', name: 'LATAM Distribution Center', country: 'Brazil' },
  ]
  const warehouseRows = warehouseDefs.map((w, i) => [num(i + 1), str(w.code), str(w.name), str(w.country)])
  statements.push(insertStatement('warehouses', ['id', 'code', 'name', 'country'], warehouseRows))

  // ---------------------------------------------------------------- employees
  type Employee = { id: number; departmentId: number; managerId: number | null; title: string; salary: number; isActive: boolean }
  const employees: Employee[] = []
  const deptEmployeeCount: Record<string, number> = {
    Executive: 5,
    Sales: 8,
    'Sales - Enterprise': 12,
    'Sales - SMB': 14,
    Engineering: 10,
    'Engineering - Platform': 18,
    'Engineering - Mobile': 16,
    'Customer Success': 6,
    'Support - Tier 1': 20,
    'Support - Tier 2': 14,
    Marketing: 12,
    Operations: 8,
    'Warehouse Operations': 17,
  }
  const execTitles = ['Chief Executive Officer', 'Chief Financial Officer', 'Chief Technology Officer', 'VP of Operations', 'VP of People']
  const titlesByDept = (deptName: string): { head: string; ic: string[] } => {
    if (deptName === 'Executive') return { head: 'Chief Executive Officer', ic: execTitles }
    if (deptName.startsWith('Sales')) return { head: 'Sales Director', ic: ['Account Executive', 'Sales Development Rep', 'Sales Manager'] }
    if (deptName.startsWith('Engineering')) return { head: 'Engineering Manager', ic: ['Software Engineer', 'Senior Software Engineer', 'Staff Engineer', 'QA Engineer'] }
    if (deptName === 'Customer Success') return { head: 'Director of Customer Success', ic: ['Customer Success Manager'] }
    if (deptName.startsWith('Support')) return { head: 'Support Team Lead', ic: ['Support Agent', 'Senior Support Agent'] }
    if (deptName === 'Marketing') return { head: 'Marketing Director', ic: ['Marketing Specialist', 'Content Strategist', 'SEO Analyst'] }
    if (deptName === 'Operations') return { head: 'Director of Operations', ic: ['Operations Analyst'] }
    return { head: 'Warehouse Supervisor', ic: ['Warehouse Associate', 'Logistics Coordinator'] }
  }
  const deptHead = new Map<string, number>()
  const usedEmails = new Set<string>()
  let empId = 1
  for (const d of DEPARTMENTS) {
    const count = deptEmployeeCount[d.name] ?? 6
    const { head, ic } = titlesByDept(d.name)
    const parentHeadId = d.parent ? (deptHead.get(d.parent) ?? null) : null
    for (let i = 0; i < count; i++) {
      const isHead = i === 0
      const title = isHead ? head : rng.pick(ic)
      const managerId = isHead ? parentHeadId : (deptHead.get(d.name) ?? parentHeadId)
      const baseSalary = isHead ? rng.numeric(105000, 175000) : rng.numeric(52000, 118000)
      employees.push({ id: empId, departmentId: deptIdByName.get(d.name)!, managerId, title, salary: baseSalary, isActive: rng.bool(0.94) })
      if (isHead) deptHead.set(d.name, empId)
      empId++
    }
  }
  const empRows: string[][] = employees.map((e) => {
    const { first, last } = fullName(rng)
    let email = `${first.toLowerCase()}.${last.toLowerCase()}@northstarretail.com`
    let n = 1
    while (usedEmails.has(email)) {
      email = `${first.toLowerCase()}.${last.toLowerCase()}${n}@northstarretail.com`
      n++
    }
    usedEmails.add(email)
    const hireDate = rng.dateBetween(new Date('2016-01-01'), new Date('2025-06-01'))
    const skillsPool = ['excel', 'salesforce', 'sql', 'communication', 'leadership', 'python', 'zendesk', 'figma', 'project-management']
    const skills = rng.pickN(skillsPool, rng.int(1, 4))
    const terminationDate = !e.isActive ? rng.dateBetween(hireDate, NOW) : null
    return [
      num(e.id),
      str(first),
      str(last),
      str(email),
      num(e.departmentId),
      num(e.managerId),
      str(e.title),
      num(e.salary),
      dateOnly(hireDate),
      terminationDate ? dateOnly(terminationDate) : 'NULL',
      bool(e.isActive),
      textArray(skills),
      json({ remote: rng.bool(0.4), level: rng.pick(['junior', 'mid', 'senior', 'lead']) }),
    ]
  })
  for (const stmt of batchedInserts(
    'employees',
    ['id', 'first_name', 'last_name', 'email', 'department_id', 'manager_id', 'title', 'salary', 'hire_date', 'termination_date', 'is_active', 'skills', 'metadata'],
    empRows,
  )) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- categories
  const categoryIdByName = new Map<string, number>()
  const catRows: string[][] = []
  let catId = 1
  const leafCategories: { id: number; name: string }[] = []
  const rootCategoryIds: number[] = []
  for (const root of CATEGORY_TREE) {
    const rootId = catId++
    categoryIdByName.set(root.name, rootId)
    rootCategoryIds.push(rootId)
    catRows.push([num(rootId), str(root.name), str(slugify(root.name)), 'NULL'])
    for (const child of root.children) {
      const childId = catId++
      categoryIdByName.set(child, childId)
      leafCategories.push({ id: childId, name: child })
      catRows.push([num(childId), str(child), str(slugify(child)), num(rootId)])
    }
  }
  statements.push(insertStatement('categories', ['id', 'name', 'slug', 'parent_category_id'], catRows))

  // ---------------------------------------------------------------- suppliers
  const supplierCount = 45
  const supplierRows: string[][] = []
  for (let i = 1; i <= supplierCount; i++) {
    const country = rng.pick(COUNTRIES).country
    const name = `${rng.pick(BRANDS)} ${rng.pick(['Manufacturing', 'Goods Co.', 'Industries', 'Supply Co.', 'Trading', 'Group'])}`
    supplierRows.push([
      num(i),
      str(name),
      str(country),
      str(`contact@${slugify(name)}.com`),
      num(rng.numeric(2.5, 5.0, 1)),
    ])
  }
  statements.push(insertStatement('suppliers', ['id', 'name', 'country', 'contact_email', 'rating'], supplierRows))

  // ---------------------------------------------------------------- products
  type Product = { id: string; categoryId: number; categoryName: string; price: number; createdAt: Date; status: string }
  const products: Product[] = []
  const productRows: string[][] = []
  const usedSkus = new Set<string>()
  for (const leaf of leafCategories) {
    const nouns = PRODUCT_NOUNS[leaf.name] ?? ['Item']
    const countForLeaf = rng.int(14, 22)
    for (let i = 0; i < countForLeaf; i++) {
      const brand = rng.pick(BRANDS)
      const adj = rng.pick(PRODUCT_ADJECTIVES)
      const noun = rng.pick(nouns)
      const name = `${brand} ${adj} ${noun}`
      let sku = `${slugify(brand)}-${slugify(noun)}-${rng.int(1000, 9999)}`.toUpperCase()
      while (usedSkus.has(sku)) sku = `${sku}${rng.int(0, 9)}`
      usedSkus.add(sku)
      const cost = rng.numeric(5, 400)
      const price = Math.round(cost * rng.numeric(1.4, 2.6) * 100) / 100
      const createdAt = rng.dateBetween(new Date('2021-01-01'), new Date('2026-06-01'))
      const status = rng.weighted([
        ['active', 88],
        ['discontinued', 8],
        ['draft', 4],
      ] as const)
      const discontinuedAt = status === 'discontinued' ? rng.dateBetween(createdAt, NOW) : null
      const id = rng.uuid()
      products.push({ id, categoryId: leaf.id, categoryName: leaf.name, price, createdAt, status })
      const tagsPool = ['bestseller', 'new-arrival', 'eco-friendly', 'limited-edition', 'staff-pick', 'clearance', 'imported']
      productRows.push([
        str(id),
        str(sku),
        str(name),
        num(leaf.id),
        num(rng.int(1, supplierCount)),
        num(price),
        num(cost),
        num(rng.int(0, 800)),
        str(status),
        textArray(rng.pickN(tagsPool, rng.int(0, 3))),
        json({ weightKg: rng.numeric(0.05, 25, 2), color: rng.pick(['black', 'white', 'silver', 'blue', 'red', 'green', 'natural']), warrantyMonths: rng.pick([0, 6, 12, 24]) }),
        ts(createdAt),
        discontinuedAt ? ts(discontinuedAt) : 'NULL',
      ])
    }
  }
  for (const stmt of batchedInserts(
    'products',
    ['id', 'sku', 'name', 'category_id', 'supplier_id', 'price', 'cost', 'inventory_count', 'status', 'tags', 'attributes', 'created_at', 'discontinued_at'],
    productRows,
  )) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- inventory
  const inventoryRows: string[][] = []
  for (const p of products) {
    const warehouseIds = rng.pickN([1, 2, 3, 4, 5, 6], rng.int(1, 4))
    for (const wId of warehouseIds) {
      inventoryRows.push([num(wId), str(p.id), num(rng.int(0, 500))])
    }
  }
  for (const stmt of batchedInserts('inventory', ['warehouse_id', 'product_id', 'quantity'], inventoryRows)) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- customers
  type Customer = { id: string; signupDate: Date; country: string; tier: string }
  const customerCount = 2000
  const customers: Customer[] = []
  const customerRows: string[][] = []
  const custUsedEmails = new Set<string>()
  for (let i = 0; i < customerCount; i++) {
    const { first, last } = fullName(rng)
    const countryEntry = rng.pick(COUNTRIES)
    const signupDate = rng.dateBetween(new Date('2022-01-01'), NOW)
    const tier = rng.weighted([
      ['bronze', 50],
      ['silver', 28],
      ['gold', 15],
      ['platinum', 7],
    ] as const)
    let email = `${first.toLowerCase()}.${last.toLowerCase()}${rng.int(1, 999)}@${rng.pick(['gmail.com', 'outlook.com', 'yahoo.com', 'mail.com', 'proton.me'])}`
    while (custUsedEmails.has(email)) email = `${first.toLowerCase()}.${last.toLowerCase()}${rng.int(1000, 9999)}@example.com`
    custUsedEmails.add(email)
    const id = rng.uuid()
    const referredBy = customers.length > 20 && rng.bool(0.12) ? rng.pick(customers).id : null
    const hasBirth = rng.bool(0.75)
    const tagsPool = ['newsletter', 'vip', 'wholesale', 'influencer', 'early-adopter', 'churn-risk']
    customers.push({ id, signupDate, country: countryEntry.country, tier })
    customerRows.push([
      str(id),
      str(email),
      str(first),
      str(last),
      dateOnly(signupDate),
      str(tier),
      str(countryEntry.country),
      hasBirth ? dateOnly(rng.dateBetween(new Date('1955-01-01'), new Date('2007-01-01'))) : 'NULL',
      bool(rng.bool(0.68)),
      referredBy ? str(referredBy) : 'NULL',
      textArray(rng.pickN(tagsPool, rng.int(0, 2))),
      json({ acquisitionChannel: rng.pick(['organic', 'paid-search', 'social', 'referral', 'email', 'affiliate']), lifetimeSupportContacts: rng.int(0, 6) }),
    ])
  }
  for (const stmt of batchedInserts(
    'customers',
    ['id', 'email', 'first_name', 'last_name', 'signup_date', 'tier', 'country', 'birth_date', 'marketing_opt_in', 'referred_by', 'tags', 'metadata'],
    customerRows,
  )) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- addresses
  type Address = { id: number; customerId: string; kind: 'billing' | 'shipping' }
  const addresses: Address[] = []
  const addressRows: string[][] = []
  let addrId = 1
  for (const c of customers) {
    const countryEntry = COUNTRIES.find((x) => x.country === c.country)!
    const numAddresses = rng.bool(0.3) ? 2 : 1
    for (let i = 0; i < numAddresses; i++) {
      const kind: 'billing' | 'shipping' = i === 0 ? 'billing' : 'shipping'
      const city = rng.pick(countryEntry.cities)
      addresses.push({ id: addrId, customerId: c.id, kind })
      addressRows.push([
        num(addrId),
        str(c.id),
        str(kind),
        str(`${rng.int(10, 9999)} ${rng.pick(STREET_NAMES)} St.`),
        str(city),
        str(c.country),
        str(String(rng.int(10000, 99999))),
        bool(i === 0),
      ])
      addrId++
    }
  }
  for (const stmt of batchedInserts('addresses', ['id', 'customer_id', 'kind', 'line1', 'city', 'country', 'postal_code', 'is_default'], addressRows)) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- memberships
  const membershipRows: string[][] = []
  let memId = 1
  for (const c of customers) {
    if (!rng.bool(0.45)) continue
    const plan = rng.weighted([
      ['basic', 40],
      ['plus', 30],
      ['premium', 20],
      ['elite', 10],
    ] as const)
    const fee = { basic: 4.99, plus: 9.99, premium: 19.99, elite: 39.99 }[plan]
    const startedAt = rng.dateBetween(c.signupDate, NOW)
    const status = rng.weighted([
      ['active', 65],
      ['cancelled', 15],
      ['trialing', 10],
      ['past_due', 10],
    ] as const)
    const endedAt = status === 'cancelled' && startedAt < NOW ? rng.dateBetween(startedAt, NOW) : null
    membershipRows.push([num(memId), str(c.id), str(plan), str(status), num(fee), dateOnly(startedAt), endedAt ? dateOnly(endedAt) : 'NULL'])
    memId++
  }
  for (const stmt of batchedInserts('memberships', ['id', 'customer_id', 'plan', 'status', 'monthly_fee', 'started_at', 'ended_at'], membershipRows)) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- coupons
  type Coupon = { id: number; code: string; validFrom: Date; validTo: Date }
  const couponDefs = [
    'WELCOME10', 'SAVE15', 'SUMMER20', 'WINTER25', 'FLASH30', 'VIP10', 'FREESHIP', 'HOLIDAY15',
    'NEWYEAR20', 'SPRING10', 'LOYALTY5', 'BUNDLE15', 'CLEARANCE25', 'MEMBER10', 'FIRSTORDER',
    'BLACKFRIDAY', 'CYBERMON30', 'REFER10', 'BDAY15', 'RESTOCK5', 'ANNIVERSARY20', 'STUDENT10',
    'WEEKEND15', 'GIFT10', 'EXTRA5', 'SAVEBIG25', 'EARLYBIRD', 'FLASH50', 'THANKYOU10', 'RESTART15',
  ]
  const coupons: Coupon[] = []
  const couponRows: string[][] = []
  couponDefs.forEach((code, i) => {
    const id = i + 1
    const validFrom = rng.dateBetween(new Date('2023-01-01'), new Date('2026-01-01'))
    const validTo = new Date(validFrom.getTime() + rng.int(20, 200) * DAY)
    coupons.push({ id, code, validFrom, validTo })
    const applicable = rng.bool(0.4) ? rng.pickN(rootCategoryIds, rng.int(1, 3)) : null
    couponRows.push([
      num(id),
      str(code),
      num(rng.numeric(5, 30, 0)),
      dateOnly(validFrom),
      dateOnly(validTo),
      rng.bool(0.5) ? num(rng.int(50, 5000)) : 'NULL',
      applicable ? intArray(applicable) : 'NULL',
    ])
  })
  statements.push(insertStatement('coupons', ['id', 'code', 'discount_pct', 'valid_from', 'valid_to', 'max_uses', 'applicable_category_ids'], couponRows))

  // ---------------------------------------------------------------- orders + order_items + payments + order_coupons
  const salesRepPool = employees.filter((_e, idx) => employees[idx].departmentId >= 2 && employees[idx].departmentId <= 4).map((e) => e.id)
  const activeProducts = products.filter((p) => p.status !== 'draft')

  const orderCount = 7000
  type OrderRec = { id: number; customerId: string; orderDate: Date; status: string }
  const orders: OrderRec[] = []
  const orderRows: string[][] = []
  const orderItemRows: string[][] = []
  const paymentRows: string[][] = []
  const orderCouponRows: string[][] = []
  const customerAddresses = new Map<string, Address[]>()
  for (const a of addresses) {
    const list = customerAddresses.get(a.customerId) ?? []
    list.push(a)
    customerAddresses.set(a.customerId, list)
  }

  let orderItemId = 1
  let paymentId = 1
  for (let i = 1; i <= orderCount; i++) {
    // Weight toward repeat customers by biasing pick toward earlier-signed-up customers occasionally.
    const customer = rng.pick(customers)
    const orderDate = rng.dateBetween(new Date(Math.max(customer.signupDate.getTime(), new Date('2022-01-01').getTime())), NOW)
    const status = rng.weighted([
      ['delivered', 62],
      ['shipped', 12],
      ['processing', 8],
      ['pending', 6],
      ['cancelled', 7],
      ['refunded', 5],
    ] as const)
    const custAddrs = customerAddresses.get(customer.id)
    const shippingAddr = custAddrs ? rng.pick(custAddrs) : null
    const employeeId = rng.bool(0.55) ? rng.pick(salesRepPool) : null
    orders.push({ id: i, customerId: customer.id, orderDate, status })
    orderRows.push([
      num(i),
      str(`NS-${100000 + i}`),
      str(customer.id),
      employeeId ? num(employeeId) : 'NULL',
      ts(orderDate),
      str(status),
      shippingAddr ? num(shippingAddr.id) : 'NULL',
      rng.bool(0.08) ? str(rng.pick(['Gift wrap requested', 'Leave at front door', 'Call on arrival', 'Fragile items inside'])) : 'NULL',
    ])

    const itemCount = rng.int(1, 5)
    let orderTotal = 0
    const chosenProducts = rng.pickN(activeProducts, Math.min(itemCount, activeProducts.length))
    for (const p of chosenProducts) {
      const quantity = rng.int(1, 4)
      const discountPct = rng.bool(0.2) ? rng.numeric(5, 20, 0) : 0
      const lineTotal = p.price * quantity * (1 - discountPct / 100)
      orderTotal += lineTotal
      orderItemRows.push([num(orderItemId), num(i), str(p.id), num(quantity), num(p.price), num(discountPct)])
      orderItemId++
    }

    if (rng.bool(0.16) && coupons.length > 0) {
      const validCoupons = coupons.filter((c) => orderDate >= c.validFrom && orderDate <= c.validTo)
      if (validCoupons.length > 0) {
        const coupon = rng.pick(validCoupons)
        orderCouponRows.push([num(i), num(coupon.id)])
      }
    }

    const paymentStatus = status === 'refunded' ? 'refunded' : status === 'cancelled' ? (rng.bool(0.5) ? 'failed' : 'refunded') : 'completed'
    const paidAt = new Date(orderDate.getTime() + rng.int(0, 3) * 60 * 60 * 1000)
    paymentRows.push([
      num(paymentId),
      num(i),
      num(Math.round(orderTotal * 100) / 100),
      ts(paidAt),
      str(rng.weighted([
        ['credit_card', 60],
        ['paypal', 25],
        ['bank_transfer', 8],
        ['gift_card', 7],
      ] as const)),
      str(paymentStatus),
    ])
    paymentId++
  }

  for (const stmt of batchedInserts(
    'orders',
    ['id', 'order_number', 'customer_id', 'employee_id', 'order_date', 'status', 'shipping_address_id', 'notes'],
    orderRows,
  )) statements.push(stmt)
  for (const stmt of batchedInserts('order_items', ['id', 'order_id', 'product_id', 'quantity', 'unit_price', 'discount_pct'], orderItemRows)) statements.push(stmt)
  for (const stmt of batchedInserts('payments', ['id', 'order_id', 'amount', 'paid_at', 'method', 'status'], paymentRows)) statements.push(stmt)
  if (orderCouponRows.length > 0) {
    for (const stmt of batchedInserts('order_coupons', ['order_id', 'coupon_id'], orderCouponRows)) statements.push(stmt)
  }

  // ---------------------------------------------------------------- reviews
  const reviewCount = 3500
  const reviewRows: string[][] = []
  const reviewTitlesPositive = ['Exceeded expectations', 'Great value', 'Works perfectly', 'Highly recommend', 'Exactly as described', 'Love it']
  const reviewTitlesNegative = ['Disappointed', 'Not worth it', 'Had issues', 'Would not buy again', 'Below expectations']
  for (let i = 1; i <= reviewCount; i++) {
    const product = rng.pick(products)
    const customer = rng.pick(customers)
    const rating = rng.weighted([
      [5, 42],
      [4, 28],
      [3, 14],
      [2, 9],
      [1, 7],
    ] as const)
    const createdAt = rng.dateBetween(new Date(Math.max(product.createdAt.getTime(), new Date('2022-01-01').getTime())), NOW)
    reviewRows.push([
      num(i),
      str(product.id),
      str(customer.id),
      num(rating),
      str(rng.pick(rating >= 4 ? reviewTitlesPositive : reviewTitlesNegative)),
      str(rng.pick([
        'Does exactly what it says on the box.',
        'Shipping was fast and packaging was solid.',
        'Quality feels a bit lower than expected for the price.',
        'Customer support was helpful when I had a question.',
        'Great addition, would purchase again.',
        'Took a while to arrive but works well.',
        'Not quite what I expected from the photos.',
        'Perfect gift, very happy with this purchase.',
      ])),
      num(rng.int(0, 240)),
      ts(createdAt),
    ])
  }
  for (const stmt of batchedInserts('reviews', ['id', 'product_id', 'customer_id', 'rating', 'title', 'body', 'helpful_votes', 'created_at'], reviewRows)) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- support tickets + messages
  const supportEmployeeIds = employees.filter((e) => e.departmentId === deptIdByName.get('Support - Tier 1') || e.departmentId === deptIdByName.get('Support - Tier 2')).map((e) => e.id)
  const ticketCount = 1500
  const ticketRows: string[][] = []
  const ticketMessageRows: string[][] = []
  let msgId = 1
  for (let i = 1; i <= ticketCount; i++) {
    const customer = rng.pick(customers)
    const createdAt = rng.dateBetween(new Date(Math.max(customer.signupDate.getTime(), new Date('2022-06-01').getTime())), NOW)
    const status = rng.weighted([
      ['closed', 55],
      ['resolved', 20],
      ['open', 15],
      ['pending', 10],
    ] as const)
    const priority = rng.weighted([
      ['low', 35],
      ['medium', 40],
      ['high', 18],
      ['urgent', 7],
    ] as const)
    const isDone = status === 'closed' || status === 'resolved'
    const resolvedAt = isDone ? new Date(createdAt.getTime() + rng.int(1, 96) * 60 * 60 * 1000) : null
    const assigned = rng.bool(0.85) ? rng.pick(supportEmployeeIds) : null
    ticketRows.push([
      num(i),
      str(customer.id),
      assigned ? num(assigned) : 'NULL',
      str(rng.pick(TICKET_SUBJECTS)),
      str(status),
      str(priority),
      ts(createdAt),
      resolvedAt ? ts(resolvedAt) : 'NULL',
      isDone && rng.bool(0.7) ? num(rng.int(1, 5)) : 'NULL',
    ])

    const msgCount = rng.int(2, 5)
    let t = createdAt.getTime()
    for (let m = 0; m < msgCount; m++) {
      const sender = m % 2 === 0 ? 'customer' : 'agent'
      t += rng.int(5, 600) * 60 * 1000
      ticketMessageRows.push([
        num(msgId),
        num(i),
        str(sender),
        str(sender === 'customer' ? 'Following up on this issue, please advise.' : 'Thanks for reaching out — looking into this now.'),
        ts(new Date(t)),
      ])
      msgId++
    }
  }
  for (const stmt of batchedInserts(
    'support_tickets',
    ['id', 'customer_id', 'assigned_employee_id', 'subject', 'status', 'priority', 'created_at', 'resolved_at', 'satisfaction_score'],
    ticketRows,
  )) statements.push(stmt)
  for (const stmt of batchedInserts('ticket_messages', ['id', 'ticket_id', 'sender', 'body', 'sent_at'], ticketMessageRows)) statements.push(stmt)

  // ---------------------------------------------------------------- events (sessionized behavioral stream)
  const sessionCount = 9000
  const eventRows: string[][] = []
  let eventId = 1
  const funnel = ['page_view', 'product_view', 'add_to_cart', 'begin_checkout', 'purchase']
  for (let s = 0; s < sessionCount; s++) {
    const sessionId = rng.uuid()
    const isAnonymous = rng.bool(0.22)
    const customer = isAnonymous ? null : rng.pick(customers)
    const sessionStart = rng.dateBetween(new Date('2025-01-01'), NOW)
    const dropoffStage = rng.weighted([
      [1, 30],
      [2, 30],
      [3, 20],
      [4, 10],
      [5, 10],
    ] as const)
    let t = sessionStart.getTime()
    for (let stage = 0; stage < dropoffStage; stage++) {
      t += rng.int(5, 300) * 1000
      eventRows.push([
        num(eventId),
        customer ? str(customer.id) : 'NULL',
        str(sessionId),
        str(funnel[stage]),
        ts(new Date(t)),
        str(`/${rng.pick(['home', 'products', 'category', 'cart', 'checkout', 'search'])}`),
        json({ device: rng.pick(['desktop', 'mobile', 'tablet']), referrer: rng.pick(['direct', 'google', 'facebook', 'email', 'affiliate']) }),
      ])
      eventId++
    }
    // sprinkle a few extra browsing events for realism
    if (rng.bool(0.3)) {
      const extra = rng.int(1, 3)
      for (let e = 0; e < extra; e++) {
        t += rng.int(5, 200) * 1000
        eventRows.push([
          num(eventId),
          customer ? str(customer.id) : 'NULL',
          str(sessionId),
          str(rng.pick(EVENT_TYPES)),
          ts(new Date(t)),
          str(`/${rng.pick(['home', 'products', 'category', 'search', 'account'])}`),
          json({ device: rng.pick(['desktop', 'mobile', 'tablet']), referrer: rng.pick(['direct', 'google', 'facebook', 'email', 'affiliate']) }),
        ])
        eventId++
      }
    }
  }
  for (const stmt of batchedInserts('events', ['id', 'customer_id', 'session_id', 'event_type', 'occurred_at', 'url', 'properties'], eventRows, 500)) {
    statements.push(stmt)
  }

  // ---------------------------------------------------------------- sync sequences
  statements.push(`SELECT setval('departments_id_seq', ${DEPARTMENTS.length});`)
  statements.push(`SELECT setval('employees_id_seq', ${employees.length});`)
  statements.push(`SELECT setval('warehouses_id_seq', ${warehouseDefs.length});`)
  statements.push(`SELECT setval('categories_id_seq', ${catId - 1});`)
  statements.push(`SELECT setval('suppliers_id_seq', ${supplierCount});`)
  statements.push(`SELECT setval('addresses_id_seq', ${addrId - 1});`)
  statements.push(`SELECT setval('memberships_id_seq', ${memId - 1});`)
  statements.push(`SELECT setval('coupons_id_seq', ${couponDefs.length});`)
  statements.push(`SELECT setval('orders_id_seq', ${orderCount});`)
  statements.push(`SELECT setval('order_items_id_seq', ${orderItemId - 1});`)
  statements.push(`SELECT setval('payments_id_seq', ${paymentId - 1});`)
  statements.push(`SELECT setval('reviews_id_seq', ${reviewCount});`)
  statements.push(`SELECT setval('support_tickets_id_seq', ${ticketCount});`)
  statements.push(`SELECT setval('ticket_messages_id_seq', ${msgId - 1});`)
  statements.push(`SELECT setval('events_id_seq', ${eventId - 1});`)

  return statements
}

export function str(value: string | null | undefined): string {
  if (value === null || value === undefined) return 'NULL'
  return `'${value.replace(/'/g, "''")}'`
}

export function num(value: number | null | undefined): string {
  if (value === null || value === undefined || Number.isNaN(value)) return 'NULL'
  return String(value)
}

export function bool(value: boolean | null | undefined): string {
  if (value === null || value === undefined) return 'NULL'
  return value ? 'true' : 'false'
}

export function textArray(values: string[] | null | undefined): string {
  if (values === null || values === undefined) return 'NULL'
  return `ARRAY[${values.map(str).join(',')}]::text[]`
}

export function intArray(values: number[] | null | undefined): string {
  if (values === null || values === undefined) return 'NULL'
  return `ARRAY[${values.join(',')}]::integer[]`
}

export function json(value: unknown): string {
  if (value === null || value === undefined) return "'{}'::jsonb"
  return `${str(JSON.stringify(value))}::jsonb`
}

export function ts(value: Date | null | undefined): string {
  if (value === null || value === undefined) return 'NULL'
  return str(value.toISOString())
}

export function dateOnly(value: Date | null | undefined): string {
  if (value === null || value === undefined) return 'NULL'
  return str(value.toISOString().slice(0, 10))
}

/** Builds a batched multi-row INSERT statement. */
export function insertStatement(table: string, columns: string[], rows: string[][]): string {
  const values = rows.map((r) => `(${r.join(',')})`).join(',\n')
  return `INSERT INTO ${table} (${columns.join(', ')}) VALUES\n${values};`
}

/** Splits rows into chunks and yields full INSERT statements per chunk. */
export function* batchedInserts(
  table: string,
  columns: string[],
  rows: string[][],
  chunkSize = 400,
): Generator<string> {
  for (let i = 0; i < rows.length; i += chunkSize) {
    yield insertStatement(table, columns, rows.slice(i, i + chunkSize))
  }
}

const NEWLINE_BEFORE = [
  'SELECT', 'FROM', 'WHERE', 'GROUP BY', 'HAVING', 'ORDER BY', 'LIMIT', 'OFFSET',
  'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'FULL JOIN', 'FULL OUTER JOIN', 'CROSS JOIN', 'JOIN',
  'UNION ALL', 'UNION', 'INTERSECT', 'EXCEPT', 'WITH', 'ON',
]

/** A lightweight, dependency-free SQL formatter: not a full parser, just
 * inserts newlines before major clause keywords and normalizes whitespace. */
export function formatSql(sql: string): string {
  let text = sql.trim().replace(/\s+/g, ' ')
  if (!text) return text

  // Protect keywords inside string literals by temporarily not touching them —
  // simple heuristic: split on unquoted regions.
  const sorted = [...NEWLINE_BEFORE].sort((a, b) => b.length - a.length)
  for (const kw of sorted) {
    const pattern = new RegExp(`\\s+(${kw.replace(/ /g, '\\s+')})\\b`, 'gi')
    text = text.replace(pattern, (_m, matched) => `\n${matched.toUpperCase()}`)
  }

  text = text.replace(/,\s*/g, ',\n  ')
  text = text.replace(/\n{2,}/g, '\n')

  return text
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .join('\n')
}

import Editor, { type OnMount } from '@monaco-editor/react'
import { useEffect, useRef } from 'react'
import { configureMonaco } from './monacoSetup'
import { DATABASE_TABLES } from '../../data/schemaExplorer'

configureMonaco()

let completionRegistered = false

function registerSchemaCompletions(monacoInstance: typeof import('monaco-editor')) {
  if (completionRegistered) return
  completionRegistered = true

  monacoInstance.languages.registerCompletionItemProvider('sql', {
    triggerCharacters: ['.', ' '],
    provideCompletionItems(model, position) {
      const word = model.getWordUntilPosition(position)
      const range = {
        startLineNumber: position.lineNumber,
        endLineNumber: position.lineNumber,
        startColumn: word.startColumn,
        endColumn: word.endColumn,
      }

      const suggestions: import('monaco-editor').languages.CompletionItem[] = []

      for (const table of DATABASE_TABLES) {
        suggestions.push({
          label: table.name,
          kind: monacoInstance.languages.CompletionItemKind.Class,
          detail: 'table',
          documentation: table.description,
          insertText: table.name,
          range,
        })
        for (const col of table.columns) {
          suggestions.push({
            label: col.name,
            kind: monacoInstance.languages.CompletionItemKind.Field,
            detail: `${table.name}.${col.name} — ${col.type}`,
            insertText: col.name,
            range,
          })
        }
      }

      return { suggestions }
    },
  })
}

interface SqlEditorProps {
  value: string
  onChange: (value: string) => void
  onRun?: () => void
  theme: 'dark' | 'light'
  readOnly?: boolean
  height?: string | number
}

export function SqlEditor({ value, onChange, onRun, theme, readOnly, height = '100%' }: SqlEditorProps) {
  const onRunRef = useRef(onRun)
  useEffect(() => {
    onRunRef.current = onRun
  }, [onRun])

  const handleMount: OnMount = (editor, monacoInstance) => {
    registerSchemaCompletions(monacoInstance)
    editor.addCommand(monacoInstance.KeyMod.CtrlCmd | monacoInstance.KeyCode.Enter, () => {
      onRunRef.current?.()
    })
  }

  return (
    <Editor
      height={height}
      defaultLanguage="sql"
      language="sql"
      value={value}
      onChange={(v) => onChange(v ?? '')}
      theme={theme === 'dark' ? 'vs-dark' : 'light'}
      onMount={handleMount}
      options={{
        fontSize: 14,
        fontFamily: "'JetBrains Mono', ui-monospace, SF Mono, Menlo, Consolas, monospace",
        minimap: { enabled: false },
        lineNumbers: 'on',
        scrollBeyondLastLine: false,
        automaticLayout: true,
        tabSize: 2,
        readOnly,
        wordWrap: 'on',
        padding: { top: 12, bottom: 12 },
        renderLineHighlight: 'gutter',
        fixedOverflowWidgets: true,
        smoothScrolling: true,
        cursorBlinking: 'smooth',
      }}
    />
  )
}

import { get, set, del } from 'idb-keyval'
import { create } from 'zustand'
import { persist, type StateStorage } from 'zustand/middleware'
import { v4 as uuidv4 } from 'uuid'
import type { QueryHistoryEntry } from '../../types'

const idbStorage: StateStorage = {
  getItem: async (name) => (await get(name)) ?? null,
  setItem: async (name, value) => {
    await set(name, value)
  },
  removeItem: async (name) => {
    await del(name)
  },
}

const MAX_ENTRIES_PER_EXERCISE = 20

interface HistoryState {
  entries: QueryHistoryEntry[]
  addEntry: (exerciseId: string, sql: string, outcome: QueryHistoryEntry['outcome']) => void
  getForExercise: (exerciseId: string) => QueryHistoryEntry[]
  deleteEntry: (id: string) => void
  clearForExercise: (exerciseId: string) => void
}

export const useHistoryStore = create<HistoryState>()(
  persist(
    (set, get) => ({
      entries: [],
      addEntry: (exerciseId, sql, outcome) =>
        set((state) => {
          const trimmedSql = sql.trim()
          if (!trimmedSql) return state
          const withoutDup = state.entries.filter((e) => !(e.exerciseId === exerciseId && e.sql === trimmedSql))
          const entry: QueryHistoryEntry = { id: uuidv4(), exerciseId, sql: trimmedSql, ranAt: Date.now(), outcome }
          const forExercise = withoutDup.filter((e) => e.exerciseId === exerciseId)
          const others = withoutDup.filter((e) => e.exerciseId !== exerciseId)
          const trimmed = [entry, ...forExercise].slice(0, MAX_ENTRIES_PER_EXERCISE)
          return { entries: [...others, ...trimmed] }
        }),
      getForExercise: (exerciseId) =>
        get()
          .entries.filter((e) => e.exerciseId === exerciseId)
          .sort((a, b) => b.ranAt - a.ranAt),
      deleteEntry: (id) => set((state) => ({ entries: state.entries.filter((e) => e.id !== id) })),
      clearForExercise: (exerciseId) => set((state) => ({ entries: state.entries.filter((e) => e.exerciseId !== exerciseId) })),
    }),
    {
      name: 'postgres-arena-history',
      storage: {
        getItem: async (name) => {
          const value = await idbStorage.getItem(name)
          return value ? JSON.parse(value as unknown as string) : null
        },
        setItem: async (name, value) => {
          await idbStorage.setItem(name, JSON.stringify(value))
        },
        removeItem: idbStorage.removeItem,
      },
    },
  ),
)

import { beforeEach, describe, expect, it } from 'vitest'
import { useProgressStore } from './store'

describe('useProgressStore', () => {
  beforeEach(() => {
    useProgressStore.getState().resetAllProgress()
  })

  it('starts an exercise as unattempted', () => {
    const state = useProgressStore.getState()
    expect(state.exercises['l1-01']).toBeUndefined()
  })

  it('marks an exercise attempted on the first recorded attempt', () => {
    useProgressStore.getState().recordAttempt('l1-01', 'SELECT 1')
    const ex = useProgressStore.getState().exercises['l1-01']
    expect(ex.status).toBe('attempted')
    expect(ex.attempts).toBe(1)
    expect(ex.lastQuery).toBe('SELECT 1')
  })

  it('increments attempts across multiple calls without resetting status', () => {
    const { recordAttempt } = useProgressStore.getState()
    recordAttempt('l1-01', 'SELECT 1')
    recordAttempt('l1-01', 'SELECT 2')
    const ex = useProgressStore.getState().exercises['l1-01']
    expect(ex.attempts).toBe(2)
    expect(ex.lastQuery).toBe('SELECT 2')
  })

  it('marks an exercise completed on a successful submission', () => {
    useProgressStore.getState().recordSubmission('l1-01', true, 'SELECT 1')
    const ex = useProgressStore.getState().exercises['l1-01']
    expect(ex.status).toBe('completed')
    expect(ex.successfulSubmissions).toBe(1)
    expect(ex.failedSubmissions).toBe(0)
    expect(ex.firstCompletedAt).toBeTypeOf('number')
  })

  it('keeps status attempted (not completed) after a failed submission', () => {
    useProgressStore.getState().recordSubmission('l1-01', false, 'SELECT wrong')
    const ex = useProgressStore.getState().exercises['l1-01']
    expect(ex.status).toBe('attempted')
    expect(ex.failedSubmissions).toBe(1)
  })

  it('does not downgrade a completed exercise back to attempted after a later failed submission', () => {
    const { recordSubmission } = useProgressStore.getState()
    recordSubmission('l1-01', true, 'SELECT correct')
    recordSubmission('l1-01', false, 'SELECT oops')
    const ex = useProgressStore.getState().exercises['l1-01']
    expect(ex.status).toBe('completed')
    expect(ex.successfulSubmissions).toBe(1)
    expect(ex.failedSubmissions).toBe(1)
  })

  it('preserves firstCompletedAt across repeated successful submissions', () => {
    const { recordSubmission } = useProgressStore.getState()
    recordSubmission('l1-01', true, 'SELECT 1')
    const firstTime = useProgressStore.getState().exercises['l1-01'].firstCompletedAt
    recordSubmission('l1-01', true, 'SELECT 1 -- again')
    const secondTime = useProgressStore.getState().exercises['l1-01'].firstCompletedAt
    expect(secondTime).toBe(firstTime)
  })

  it('tracks exercises independently by id', () => {
    const { recordAttempt } = useProgressStore.getState()
    recordAttempt('l1-01', 'a')
    recordAttempt('l2-01', 'b')
    const state = useProgressStore.getState()
    expect(state.exercises['l1-01'].attempts).toBe(1)
    expect(state.exercises['l2-01'].attempts).toBe(1)
  })

  it('resetExercise clears a single exercise without affecting others', () => {
    const { recordAttempt, resetExercise } = useProgressStore.getState()
    recordAttempt('l1-01', 'a')
    recordAttempt('l2-01', 'b')
    resetExercise('l1-01')
    const state = useProgressStore.getState()
    expect(state.exercises['l1-01']).toBeUndefined()
    expect(state.exercises['l2-01']).toBeDefined()
  })

  it('resetAllProgress clears every exercise and the current exercise pointer', () => {
    const { recordAttempt, setCurrentExercise, resetAllProgress } = useProgressStore.getState()
    recordAttempt('l1-01', 'a')
    setCurrentExercise('l1-01')
    resetAllProgress()
    const state = useProgressStore.getState()
    expect(state.exercises).toEqual({})
    expect(state.currentExerciseId).toBeNull()
  })
})

import { get, set, del } from 'idb-keyval'
import { create } from 'zustand'
import { persist, type StateStorage } from 'zustand/middleware'
import type { ExerciseProgress } from '../../types'

const idbStorage: StateStorage = {
  getItem: async (name) => (await get(name)) ?? null,
  setItem: async (name, value) => {
    await set(name, value)
  },
  removeItem: async (name) => {
    await del(name)
  },
}

interface ProgressState {
  currentExerciseId: string | null
  exercises: Record<string, ExerciseProgress>
  hasHydrated: boolean
  setHasHydrated: (v: boolean) => void
  setCurrentExercise: (exerciseId: string) => void
  recordAttempt: (exerciseId: string, query: string) => void
  recordSubmission: (exerciseId: string, ok: boolean, query: string) => void
  resetExercise: (exerciseId: string) => void
  resetAllProgress: () => void
}

function getOrCreate(state: ProgressState, exerciseId: string): ExerciseProgress {
  return (
    state.exercises[exerciseId] ?? {
      exerciseId,
      status: 'unattempted',
      attempts: 0,
      successfulSubmissions: 0,
      failedSubmissions: 0,
    }
  )
}

export const useProgressStore = create<ProgressState>()(
  persist(
    (set) => ({
      currentExerciseId: null,
      exercises: {},
      hasHydrated: false,
      setHasHydrated: (v) => set({ hasHydrated: v }),
      setCurrentExercise: (exerciseId) => set({ currentExerciseId: exerciseId }),
      recordAttempt: (exerciseId, query) =>
        set((state) => {
          const prev = getOrCreate(state, exerciseId)
          const updated: ExerciseProgress = {
            ...prev,
            attempts: prev.attempts + 1,
            lastQuery: query,
            lastAttemptAt: Date.now(),
            status: prev.status === 'unattempted' ? 'attempted' : prev.status,
          }
          return { exercises: { ...state.exercises, [exerciseId]: updated } }
        }),
      recordSubmission: (exerciseId, ok, query) =>
        set((state) => {
          const prev = getOrCreate(state, exerciseId)
          const updated: ExerciseProgress = {
            ...prev,
            lastQuery: query,
            lastAttemptAt: Date.now(),
            successfulSubmissions: prev.successfulSubmissions + (ok ? 1 : 0),
            failedSubmissions: prev.failedSubmissions + (ok ? 0 : 1),
            status: ok ? 'completed' : prev.status === 'unattempted' ? 'attempted' : prev.status,
            firstCompletedAt: ok ? (prev.firstCompletedAt ?? Date.now()) : prev.firstCompletedAt,
          }
          return { exercises: { ...state.exercises, [exerciseId]: updated } }
        }),
      resetExercise: (exerciseId) =>
        set((state) => {
          const next = { ...state.exercises }
          delete next[exerciseId]
          return { exercises: next }
        }),
      resetAllProgress: () => set({ exercises: {}, currentExerciseId: null }),
    }),
    {
      name: 'postgres-arena-progress',
      storage: {
        getItem: async (name) => {
          const value = await idbStorage.getItem(name)
          return value ? JSON.parse(value as unknown as string) : null
        },
        setItem: async (name, value) => {
          await idbStorage.setItem(name, JSON.stringify(value))
        },
        removeItem: idbStorage.removeItem,
      },
      onRehydrateStorage: () => (state) => {
        state?.setHasHydrated(true)
      },
    },
  ),
)

import { describe, expect, it } from 'vitest'
import { compareResults } from './compare'
import type { QueryResult, ValidationOptions } from '../../types'

function result(columns: string[], rows: Record<string, unknown>[]): QueryResult {
  return {
    columns: columns.map((name) => ({ name, dataTypeId: 0 })),
    rows,
    rowCount: rows.length,
    durationMs: 0,
  }
}

const unordered: ValidationOptions = { orderMatters: false }
const ordered: ValidationOptions = { orderMatters: true }

describe('compareResults — unordered (default) comparison', () => {
  it('accepts identical row order', () => {
    const a = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }])
    const b = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }])
    expect(compareResults(a, b, unordered, 0).status).toBe('ok')
  })

  it('accepts the same rows in a different order when orderMatters is false', () => {
    const user = result(['name'], [{ name: 'Bob' }, { name: 'Alice' }])
    const expected = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }])
    expect(compareResults(user, expected, unordered, 0).status).toBe('ok')
  })

  it('rejects when a row is missing', () => {
    const user = result(['name'], [{ name: 'Alice' }])
    const expected = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('missing-rows')
  })

  it('rejects when there is an extra, unexpected row', () => {
    const user = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }, { name: 'Carol' }])
    const expected = result(['name'], [{ name: 'Alice' }, { name: 'Bob' }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('unexpected-rows')
  })

  it('treats duplicate rows as significant (multiset semantics)', () => {
    const user = result(['name'], [{ name: 'Alice' }])
    const expected = result(['name'], [{ name: 'Alice' }, { name: 'Alice' }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-row-count')
  })

  it('accepts matching duplicate rows', () => {
    const a = result(['name'], [{ name: 'Alice' }, { name: 'Alice' }])
    const b = result(['name'], [{ name: 'Alice' }, { name: 'Alice' }])
    expect(compareResults(a, b, unordered, 0).status).toBe('ok')
  })

  it('rejects when column count differs', () => {
    const user = result(['name'], [{ name: 'Alice' }])
    const expected = result(['name', 'age'], [{ name: 'Alice', age: 30 }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-column-count')
  })

  it('rejects when a value differs but row/column counts match', () => {
    const user = result(['name'], [{ name: 'Alice' }])
    const expected = result(['name'], [{ name: 'Bob' }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-values')
  })

  it('reports empty-result when the user returns nothing but rows were expected', () => {
    const user = result(['name'], [])
    const expected = result(['name'], [{ name: 'Alice' }])
    const r = compareResults(user, expected, unordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('empty-result')
  })

  it('accepts two empty result sets', () => {
    const a = result(['name'], [])
    const b = result(['name'], [])
    expect(compareResults(a, b, unordered, 0).status).toBe('ok')
  })

  it('is column-name agnostic by default (only positional values matter)', () => {
    const user = result(['n'], [{ n: 'Alice' }])
    const expected = result(['name'], [{ name: 'Alice' }])
    expect(compareResults(user, expected, unordered, 0).status).toBe('ok')
  })

  it('respects roundDecimals when comparing numeric values', () => {
    const user = result(['avg'], [{ avg: '10.1' }])
    const expected = result(['avg'], [{ avg: 10.104 }])
    const r = compareResults(user, expected, { orderMatters: false, roundDecimals: 1 }, 0)
    expect(r.status).toBe('ok')
  })

  it('treats NULL as distinct from any concrete value', () => {
    const user = result(['x'], [{ x: null }])
    const expected = result(['x'], [{ x: 0 }])
    expect(compareResults(user, expected, unordered, 0).status).toBe('ko')
  })
})

describe('compareResults — ordered comparison', () => {
  it('accepts an exact match', () => {
    const a = result(['n'], [{ n: 1 }, { n: 2 }, { n: 3 }])
    const b = result(['n'], [{ n: 1 }, { n: 2 }, { n: 3 }])
    expect(compareResults(a, b, ordered, 0).status).toBe('ok')
  })

  it('rejects correct rows in the wrong order and reports wrong-order', () => {
    const user = result(['n'], [{ n: 2 }, { n: 1 }, { n: 3 }])
    const expected = result(['n'], [{ n: 1 }, { n: 2 }, { n: 3 }])
    const r = compareResults(user, expected, ordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-order')
  })

  it('rejects a differing row count even when the prefix matches', () => {
    const user = result(['n'], [{ n: 1 }, { n: 2 }])
    const expected = result(['n'], [{ n: 1 }, { n: 2 }, { n: 3 }])
    const r = compareResults(user, expected, ordered, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-row-count')
  })
})

describe('compareResults — column name enforcement', () => {
  it('rejects mismatched column names when requireColumnNames is set', () => {
    const user = result(['first'], [{ first: 'Alice' }])
    const expected = result(['first_name'], [{ first_name: 'Alice' }])
    const r = compareResults(user, expected, { orderMatters: false, requireColumnNames: true }, 0)
    expect(r.status).toBe('ko')
    expect(r.reason).toBe('wrong-column-names')
  })

  it('accepts case-insensitive column name matches', () => {
    const user = result(['Name'], [{ Name: 'Alice' }])
    const expected = result(['name'], [{ name: 'Alice' }])
    const r = compareResults(user, expected, { orderMatters: false, requireColumnNames: true }, 0)
    expect(r.status).toBe('ok')
  })
})

import type { QueryResult, ValidationOptions, ValidationResult } from '../../types'
import { normalizeRows, sortedKeys } from './normalize'

export function compareResults(userResult: QueryResult, expectedResult: QueryResult, options: ValidationOptions, durationMs: number): ValidationResult {
  const expectedRowCount = expectedResult.rows.length
  const actualRowCount = userResult.rows.length

  if (userResult.columns.length !== expectedResult.columns.length) {
    return {
      status: 'ko',
      reason: 'wrong-column-count',
      message: `Your query returns ${userResult.columns.length} column(s), but ${expectedResult.columns.length} were expected.`,
      durationMs,
      expectedRowCount,
      actualRowCount,
    }
  }

  if (options.requireColumnNames) {
    const userNames = userResult.columns.map((c) => c.name.toLowerCase())
    const expectedNames = expectedResult.columns.map((c) => c.name.toLowerCase())
    const mismatch = userNames.some((n, i) => n !== expectedNames[i])
    if (mismatch) {
      return {
        status: 'ko',
        reason: 'wrong-column-names',
        message: `Column names don't match what's expected: [${expectedNames.join(', ')}].`,
        durationMs,
        expectedRowCount,
        actualRowCount,
      }
    }
  }

  if (actualRowCount === 0 && expectedRowCount > 0) {
    return {
      status: 'ko',
      reason: 'empty-result',
      message: 'Your query returned no rows, but rows were expected.',
      durationMs,
      expectedRowCount,
      actualRowCount,
    }
  }

  const roundDecimals = options.roundDecimals
  const userRows = normalizeRows(userResult, roundDecimals)
  const expectedRows = normalizeRows(expectedResult, roundDecimals)

  if (options.orderMatters) {
    if (actualRowCount !== expectedRowCount) {
      return {
        status: 'ko',
        reason: 'wrong-row-count',
        message: `Your query returned ${actualRowCount} row(s), but ${expectedRowCount} were expected.`,
        durationMs,
        expectedRowCount,
        actualRowCount,
      }
    }
    let mismatchAt = -1
    for (let i = 0; i < userRows.length; i++) {
      if (userRows[i].key !== expectedRows[i].key) {
        mismatchAt = i
        break
      }
    }
    if (mismatchAt >= 0) {
      const userSorted = sortedKeys(userRows)
      const expectedSorted = sortedKeys(expectedRows)
      const sameContentDifferentOrder = userSorted.join('') === expectedSorted.join('')
      if (sameContentDifferentOrder) {
        return {
          status: 'ko',
          reason: 'wrong-order',
          message: `The rows are correct but not in the required order (mismatch starting at row ${mismatchAt + 1}). This exercise requires a specific ORDER BY.`,
          durationMs,
          expectedRowCount,
          actualRowCount,
        }
      }
      return {
        status: 'ko',
        reason: 'wrong-values',
        message: `Row ${mismatchAt + 1} doesn't match the expected value.`,
        durationMs,
        expectedRowCount,
        actualRowCount,
      }
    }
    return { status: 'ok', message: 'All rows match, in the correct order.', durationMs, expectedRowCount, actualRowCount }
  }

  // Order doesn't matter: compare as multisets (duplicates preserved).
  const userSorted = sortedKeys(userRows)
  const expectedSorted = sortedKeys(expectedRows)

  if (userSorted.join('') === expectedSorted.join('')) {
    return { status: 'ok', message: 'Result matches.', durationMs, expectedRowCount, actualRowCount }
  }

  if (actualRowCount !== expectedRowCount) {
    const userSet = new Set(userSorted)
    const expectedSet = new Set(expectedSorted)
    const missing = expectedSorted.filter((k) => !userSet.has(k)).length
    const unexpected = userSorted.filter((k) => !expectedSet.has(k)).length
    if (missing > 0 && unexpected === 0) {
      return {
        status: 'ko',
        reason: 'missing-rows',
        message: `Your result is missing ${missing} row(s) that should be present.`,
        durationMs,
        expectedRowCount,
        actualRowCount,
      }
    }
    if (unexpected > 0 && missing === 0) {
      return {
        status: 'ko',
        reason: 'unexpected-rows',
        message: `Your result has ${unexpected} row(s) that shouldn't be there.`,
        durationMs,
        expectedRowCount,
        actualRowCount,
      }
    }
    return {
      status: 'ko',
      reason: 'wrong-row-count',
      message: `Your query returned ${actualRowCount} row(s), but ${expectedRowCount} were expected.`,
      durationMs,
      expectedRowCount,
      actualRowCount,
    }
  }

  return {
    status: 'ko',
    reason: 'wrong-values',
    message: 'Row count matches, but some values are incorrect.',
    durationMs,
    expectedRowCount,
    actualRowCount,
  }
}

import { describe, expect, it } from 'vitest'
import { normalizeRows, sortedKeys } from './normalize'
import type { QueryResult } from '../../types'

function result(columns: string[], rows: Record<string, unknown>[]): QueryResult {
  return {
    columns: columns.map((name) => ({ name, dataTypeId: 0 })),
    rows,
    rowCount: rows.length,
    durationMs: 0,
  }
}

describe('normalizeRows', () => {
  it('treats numeric-looking strings the same as numbers (Postgres numeric columns arrive as strings)', () => {
    const asString = result(['price'], [{ price: '10.50' }])
    const asNumber = result(['price'], [{ price: 10.5 }])
    expect(normalizeRows(asString)[0].key).toBe(normalizeRows(asNumber)[0].key)
  })

  it('preserves null distinctly from 0 or empty string', () => {
    const nullRow = normalizeRows(result(['x'], [{ x: null }]))[0]
    const zeroRow = normalizeRows(result(['x'], [{ x: 0 }]))[0]
    const emptyRow = normalizeRows(result(['x'], [{ x: '' }]))[0]
    expect(nullRow.key).not.toBe(zeroRow.key)
    expect(nullRow.key).not.toBe(emptyRow.key)
  })

  it('rounds numbers to the requested number of decimals', () => {
    const rows = normalizeRows(result(['price'], [{ price: 10.126 }]), 2)
    expect(rows[0].values[0]).toBe(10.13)
  })

  it('rounds numeric-string values the same way as native numbers', () => {
    const fromString = normalizeRows(result(['price'], [{ price: '10.126' }]), 2)[0]
    const fromNumber = normalizeRows(result(['price'], [{ price: 10.126 }]), 2)[0]
    expect(fromString.key).toBe(fromNumber.key)
  })

  it('only compares selected columns, in column order — extra object keys on a row are ignored', () => {
    const columns = ['name']
    const rows = normalizeRows({ columns: columns.map((name) => ({ name, dataTypeId: 0 })), rows: [{ name: 'a', secret: 'x' }] })
    expect(rows[0].values).toEqual(['a'])
  })

  it('produces identical keys for identical rows, enabling multiset comparison', () => {
    const rows = normalizeRows(result(['a', 'b'], [{ a: 1, b: 'x' }, { a: 1, b: 'x' }]))
    expect(rows[0].key).toBe(rows[1].key)
  })
})

describe('sortedKeys', () => {
  it('sorts keys so unordered result sets can be compared as multisets', () => {
    const rows = normalizeRows(result(['n'], [{ n: 3 }, { n: 1 }, { n: 2 }]))
    expect(sortedKeys(rows)).toEqual(['[1]', '[2]', '[3]'])
  })

  it('preserves duplicate entries (does not deduplicate)', () => {
    const rows = normalizeRows(result(['n'], [{ n: 1 }, { n: 1 }, { n: 2 }]))
    expect(sortedKeys(rows)).toEqual(['[1]', '[1]', '[2]'])
  })
})

import type { QueryResult } from '../../types'

/** Converts a single cell value into a canonical, comparable primitive. */
function normalizeCell(value: unknown, roundDecimals?: number): unknown {
  if (value === null || value === undefined) return null

  if (typeof value === 'number') {
    if (roundDecimals !== undefined && Number.isFinite(value)) {
      const f = Math.pow(10, roundDecimals)
      return Math.round(value * f) / f
    }
    return value
  }

  // PGlite returns numeric/decimal columns as strings to preserve precision.
  if (typeof value === 'string' && /^-?\d+(\.\d+)?$/.test(value)) {
    const n = Number(value)
    if (roundDecimals !== undefined) {
      const f = Math.pow(10, roundDecimals)
      return Math.round(n * f) / f
    }
    // Normalize trailing zeros (e.g. "10.50" vs "10.5") without a requested rounding.
    return n
  }

  if (Array.isArray(value)) {
    return value.map((v) => normalizeCell(v, roundDecimals))
  }

  if (typeof value === 'object') {
    return value
  }

  return value
}

export interface NormalizedRow {
  values: unknown[]
  key: string
}

export function normalizeRows(result: Pick<QueryResult, 'rows' | 'columns'>, roundDecimals?: number): NormalizedRow[] {
  const columnNames = result.columns.map((c) => c.name)
  return result.rows.map((row) => {
    const values = columnNames.map((name) => normalizeCell(row[name], roundDecimals))
    return { values, key: JSON.stringify(values) }
  })
}

export function sortedKeys(rows: NormalizedRow[]): string[] {
  return rows.map((r) => r.key).sort()
}

import { runUserQuery, toQueryError } from '../../database/db'
import type { Exercise, QueryResult, ValidationResult } from '../../types'
import { compareResults } from './compare'

export interface SubmissionOutcome {
  validation: ValidationResult
  userResult?: QueryResult
}

export async function validateSubmission(exercise: Exercise, userSql: string): Promise<SubmissionOutcome> {
  const start = performance.now()

  let userResult: QueryResult
  try {
    userResult = await runUserQuery(userSql)
  } catch (err) {
    const qe = toQueryError(err)
    return {
      validation: {
        status: 'ko',
        reason: 'query-error',
        message: qe.message,
        detail: qe.detail ?? qe.hint,
        durationMs: performance.now() - start,
      },
    }
  }

  let expectedResult: QueryResult
  try {
    expectedResult = await runUserQuery(exercise.solution.sql)
  } catch (err) {
    const qe = toQueryError(err)
    // This indicates a bug in the exercise itself, not the user's query.
    console.error(`Exercise ${exercise.id} solution query failed:`, qe)
    return {
      userResult,
      validation: {
        status: 'ko',
        reason: 'query-error',
        message: 'This exercise could not be validated right now. Please report this issue.',
        durationMs: performance.now() - start,
      },
    }
  }

  return {
    userResult,
    validation: compareResults(userResult, expectedResult, exercise.validation, performance.now() - start),
  }
}

import { useEffect, useRef, useState } from 'react'
import { initDatabase, type InitProgress } from '../database/db'

export type DbInitState =
  | { status: 'initializing'; progress: InitProgress }
  | { status: 'ready' }
  | { status: 'error'; message: string }

export function useDatabase(): DbInitState {
  const [state, setState] = useState<DbInitState>({
    status: 'initializing',
    progress: { phase: 'starting', completed: 0, total: 1, message: 'Starting up...' },
  })
  const started = useRef(false)

  useEffect(() => {
    if (started.current) return
    started.current = true
    initDatabase((progress) => setState({ status: 'initializing', progress }))
      .then(() => setState({ status: 'ready' }))
      .catch((err) => setState({ status: 'error', message: err instanceof Error ? err.message : String(err) }))
  }, [])

  return state
}

import { useEffect, useState } from 'react'

export type Theme = 'dark' | 'light'

const STORAGE_KEY = 'postgres-arena-theme'

function getInitialTheme(): Theme {
  if (typeof window === 'undefined') return 'dark'
  const stored = window.localStorage.getItem(STORAGE_KEY)
  if (stored === 'dark' || stored === 'light') return stored
  return window.matchMedia?.('(prefers-color-scheme: light)').matches ? 'light' : 'dark'
}

export function useTheme(): [Theme, () => void] {
  const [theme, setTheme] = useState<Theme>(getInitialTheme)

  useEffect(() => {
    document.documentElement.classList.toggle('light', theme === 'light')
    window.localStorage.setItem(STORAGE_KEY, theme)
  }, [theme])

  const toggle = () => setTheme((t) => (t === 'dark' ? 'light' : 'dark'))
  return [theme, toggle]
}

